insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('niacinamide','나이아신아마이드','Niacinamide',array['tone','barrier','sebum']::text[],'rose','피부 톤을 고르게 보이도록 돕고 장벽·피지 관리에 두루 쓰이는 수용성 비타민 B3 계열 성분이에요.','니코틴아마이드라고도 불리는 비타민 B3의 아마이드 형태로, 멜라노솜이 각질형성세포로 이동하는 과정을 줄이고 세라마이드 합성을 돕는 것으로 보고돼 있어요. 화장품에는 대체로 2~5% 정도로 배합되고, 국내에서는 미백 기능성 고시 원료(2%)로 등록돼 있어요. pH 5~7의 중성 부근에서 안정적이라 아침·저녁 모두 쓰기 무난하고, 다른 활성 성분과 조합하기 쉬운 편이에요. 다만 10% 이상 고농도에서는 일시적인 홍조나 따끔함이 나타나는 경우도 있어 처음엔 낮은 농도부터 시작하는 편이 권장돼요.',array['hyaluronic-acid','ceramide','retinol','peptides']::text[],array['ascorbic-acid']::text[],array['pigmentation','texture','sebum','barrier','dullness']::text[],'Bissett DL et al., Dermatol Surg 2005; Hakozaki T et al., Br J Dermatol 2002','high','2026-08-20',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('ascorbic-acid','아스코빅애씨드(순수 비타민C)','Ascorbic Acid',array['tone','antioxidant']::text[],'rose','항산화와 톤 케어에 자주 쓰이는 순수 비타민C예요. 산화가 빨라 제형 안정성이 특히 중요한 성분이에요.','L-아스코빅애씨드는 티로시나아제 활성을 낮추고 활성산소를 중화하며 콜라겐 합성의 보조인자로 작용하는 것으로 알려져 있어요. 피부 흡수를 위해 pH 3.5 이하의 저 pH 환경과 10~20% 농도가 흔히 사용되고, 토코페롤·페룰릭애씨드와 함께 배합하면 안정성이 높아진다고 보고돼요. 공기와 빛에 노출되면 갈변하며 산화되므로 개봉 후엔 빠르게 쓰는 편이 좋고, 저 pH 특성 때문에 처음엔 따끔함이나 홍조가 있을 수 있어요. 아침에 자외선차단제 아래 바르는 조합이 자주 언급돼요.',array['tocopherol','ferulic-acid','hyaluronic-acid']::text[],array['retinol','niacinamide','copper-peptide','benzoyl-peroxide']::text[],array['pigmentation','dullness','firming']::text[],'Lin FH et al., J Invest Dermatol 2005; Pinnell SR et al., Dermatol Surg 2001','high','2026-08-20',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('ascorbyl-glucoside','아스코빌글루코사이드','Ascorbyl Glucoside',array['tone','antioxidant']::text[],'rose','순수 비타민C에 포도당을 붙여 안정화한 유도체예요. 자극이 적은 편이라 입문용으로 자주 소개돼요.','아스코빅애씨드의 2번 위치에 글루코스가 결합된 수용성 유도체로, 피부의 알파-글루코시다아제에 의해 서서히 비타민C로 전환되는 것으로 알려져 있어요. 중성 부근 pH에서도 비교적 안정적이라 순수형처럼 저 pH가 필요하지 않고, 국내 미백 기능성 고시 원료(2%)로 등록돼 있어요. 전환 효율이 높지 않아 작용 강도는 순수형보다 낮은 편으로 언급되지만, 그만큼 따끔함이 덜해 나이아신아마이드 등과 함께 쓰기 무난해요. 아침·저녁 모두 사용할 수 있어요.',array['niacinamide','hyaluronic-acid','alpha-arbutin','tocopherol']::text[],'{}'::text[],array['dullness','pigmentation']::text[],'Kumano Y et al., J Nutr Sci Vitaminol 1998; 식약처 기능성화장품 고시 원료','moderate','2026-08-12',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('ethyl-ascorbic-acid','에틸아스코빅애씨드','3-O-Ethyl Ascorbic Acid',array['tone','antioxidant']::text[],'rose','비타민C에 에틸기를 붙여 안정성과 지용성을 높인 유도체예요. 톤 케어 세럼에 자주 들어가요.','3-O-에틸아스코빅애씨드는 비타민C의 3번 위치 하이드록시기를 에틸화한 형태로, 산화에 비교적 강하고 물과 기름 양쪽에 어느 정도 녹아 피부 투과가 유리한 것으로 소개돼요. 피부 안에서 효소 작용으로 아스코빅애씨드로 전환된다고 알려져 있으며, 배합 농도는 보통 1~5% 정도예요. 순수형보다 pH 제약이 덜해 자극이 낮은 편이지만, 고농도 제품에서는 개인에 따라 따끔함이 나타날 수 있어요. 아침 사용 시 자외선차단제와 함께 쓰는 조합이 자주 언급돼요.',array['niacinamide','ferulic-acid','hyaluronic-acid','tocopherol']::text[],'{}'::text[],array['pigmentation','dullness']::text[],'Iliopoulos F et al., Int J Pharm 2019; CIR Expert Panel','moderate','2026-08-12',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('sodium-ascorbyl-phosphate','소듐아스코빌포스페이트','Sodium Ascorbyl Phosphate',array['tone','sebum']::text[],'rose','인산염 형태로 안정화한 비타민C 유도체예요. 트러블 경향 피부의 톤 케어에 자주 쓰여요.','아스코빅애씨드에 인산기와 나트륨이 결합한 수용성 유도체로, 피부의 포스파타아제에 의해 비타민C로 전환되는 것으로 알려져 있어요. 중성~약알칼리 pH에서 안정적이라 제형에 넣기 쉽고, 1~5% 농도에서 트러블 병변 수가 줄었다는 소규모 임상 보고가 있어 트러블 라인에 자주 배합돼요. 순수형보다 작용은 완만하지만 자극이 적은 편이라 나이아신아마이드, 살리실릭애씨드와 함께 쓰기 무난해요. 다만 낮은 pH 제형과 함께 쓰면 안정성이 떨어질 수 있어요.',array['niacinamide','salicylic-acid','hyaluronic-acid','zinc-pca']::text[],array['glycolic-acid']::text[],array['breakout','dullness']::text[],'Woolery-Lloyd H et al., J Cosmet Dermatol 2010; CIR Expert Panel','moderate','2026-08-12',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('alpha-arbutin','알파-알부틴','Alpha-Arbutin',array['tone']::text[],'rose','하이드로퀴논에 당을 붙인 구조의 톤 케어 성분이에요. 잡티·흔적 관리 제품에 자주 배합돼요.','알파-알부틴은 하이드로퀴논의 알파-글루코사이드로, 멜라닌 합성 효소인 티로시나아제의 활성을 경쟁적으로 억제하는 것으로 알려져 있어요. 베타-알부틴보다 티로시나아제 억제력이 높다고 보고되며, 화장품에는 보통 1~2% 농도로 배합돼요. 국내에서는 알부틴이 미백 기능성 고시 원료(2~5%)로 관리되고 있어요. 수용성이고 pH 제약이 크지 않아 나이아신아마이드, 트라넥사믹애씨드, 비타민C 유도체와 조합하는 처방이 흔하고, 결과를 보려면 수 주 이상 꾸준히 자외선차단제와 함께 쓰는 편이 권장돼요.',array['niacinamide','tranexamic-acid','ascorbyl-glucoside','licorice']::text[],'{}'::text[],array['pigmentation','dullness']::text[],'SCCS Opinion on alpha-arbutin (2015); Sugimoto K et al., Chem Pharm Bull 2004','moderate','2026-07-28',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('tranexamic-acid','트라넥사믹애씨드','Tranexamic Acid',array['tone']::text[],'rose','원래 지혈제로 쓰이던 아미노산 유도체예요. 잡티·흔적 톤 케어 제품에 최근 자주 보이는 성분이에요.','트라넥사믹애씨드는 라이신 유사 구조의 합성 아미노산으로, 플라스민 활성을 억제해 자외선 자극 후 각질형성세포에서 멜라노사이트로 전달되는 신호를 줄이는 것으로 알려져 있어요. 국소 도포 연구에서는 2~5% 농도가 주로 쓰였고, 기미 관련 지표 개선이 보고된 바 있어요. 수용성이고 자극이 낮은 편이라 나이아신아마이드, 알부틴, 비타민C 유도체와 함께 배합하는 처방이 흔하며, 아침·저녁 모두 사용할 수 있어요. 톤 케어 성분이 대개 그렇듯 자외선차단제와 함께 쓰는 편이 권장돼요.',array['niacinamide','alpha-arbutin','ascorbyl-glucoside','azelaic-acid']::text[],'{}'::text[],array['pigmentation']::text[],'Kim SJ et al., Acta Derm Venereol 2016; Maeda K & Naganuma M, J Photochem Photobiol B 1998','moderate','2026-07-28',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('azelaic-acid','아젤라익애씨드','Azelaic Acid',array['tone','sebum','soothing']::text[],'rose','곡물 발효에서 유래한 다이카복실산이에요. 톤·피지·트러블 관련 제품에 두루 등장해요.','아젤라익애씨드는 티로시나아제 억제, 각질 형성 정상화, 큐티박테리움 아크네스 억제 등 여러 작용이 보고된 성분이에요. 의약품으로는 15~20%가 쓰이고 화장품에는 보통 10% 이하로 배합되며, 국내 화장품에서는 배합 한도가 있어요. 물에 잘 녹지 않아 제형 기술이 중요하고, 초반에는 따끔함·가려움이 일시적으로 나타날 수 있어 격일로 시작하는 편이 권장돼요. 나이아신아마이드, 판테놀과 조합이 무난하고, 레티노이드나 각질 관리 산과 같은 날 겹쳐 쓰면 자극이 누적될 수 있어요.',array['niacinamide','panthenol','centella','tranexamic-acid']::text[],array['retinol','glycolic-acid','salicylic-acid']::text[],array['pigmentation','breakout','sebum']::text[],'Fitton A & Goa KL, Drugs 1991; Draelos ZD, Cosmetic Dermatology (2015)','high','2026-08-05',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('kojic-acid','코직애씨드','Kojic Acid',array['tone']::text[],'rose','누룩곰팡이 발효에서 얻는 톤 케어 성분이에요. 오래 쓰여 왔지만 빛과 열에 약한 편이에요.','코직애씨드는 아스페르길루스 발효 산물로, 티로시나아제의 구리 이온을 킬레이트해 멜라닌 합성을 늦추는 것으로 알려져 있어요. 화장품에는 보통 1~2% 농도로 쓰이며, 빛과 열에 약해 갈변하기 쉬워 디팔미테이트 등 유도체 형태로 배합하기도 해요. 접촉 알레르기 보고가 있어 SCCS는 1% 이하 사용을 권고하고 있고, 민감한 편이라면 팔 안쪽에 소량 테스트 후 쓰는 편이 권장돼요. 알부틴, 비타민C 유도체, 나이아신아마이드와 조합하는 처방이 흔하고, 자외선차단제와 함께 쓰는 편이 좋아요.',array['alpha-arbutin','niacinamide','ascorbyl-glucoside','licorice']::text[],array['retinol','glycolic-acid']::text[],array['pigmentation']::text[],'SCCS Opinion on kojic acid (2012); Saeedi M et al., Biomed Pharmacother 2019','moderate','2026-08-05',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('licorice','감초뿌리추출물','Glycyrrhiza Glabra (Licorice) Root Extract',array['tone','soothing']::text[],'rose','감초 뿌리에서 얻는 추출물이에요. 진정과 톤 케어 두 가지 목적으로 자주 배합되는 식물 성분이에요.','감초뿌리추출물에는 글라브리딘, 리퀴리틴, 글리시리진산 같은 플라보노이드와 트리테르펜이 들어 있어요. 글라브리딘은 티로시나아제 억제와 항산화 작용이, 글리시리진산은 염증 관련 신호 완화가 보고돼 있어 톤 케어와 진정 라인 양쪽에 쓰여요. 추출 방식과 표준화 정도에 따라 성분 함량 차이가 커서 제품마다 체감이 다를 수 있어요. 자극이 낮은 편이라 나이아신아마이드, 알부틴, 병풀추출물과 함께 배합하기 무난하고, 아침·저녁 모두 사용할 수 있어요.',array['niacinamide','alpha-arbutin','centella','tranexamic-acid']::text[],'{}'::text[],array['pigmentation','dullness','breakout']::text[],'Yokota T et al., Pigment Cell Res 1998; CIR Expert Panel Final Report (Glycyrrhiza)','moderate','2026-07-15','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('thiamidol','티아미돌','Isobutylamido Thiazolyl Resorcinol',array['tone']::text[],'rose','사람 티로시나아제를 겨냥해 설계된 비교적 새로운 톤 케어 성분이에요. 잡티·흔적 제품에 쓰여요.','이소부틸아미도티아졸릴레조시놀(티아미돌)은 사람 티로시나아제에 대한 억제력을 기준으로 선별된 레조시놀 계열 합성 성분이에요. 기존 성분 상당수가 버섯 유래 티로시나아제로 평가된 것과 달리 사람 효소를 기준으로 개발됐고, 0.2% 농도의 임상 연구에서 기미 관련 지표 개선이 보고돼 있어요. 특정 제조사의 특허 성분이라 접할 수 있는 제품이 제한적이에요. 자극은 낮은 편으로 알려져 있으나 독립적인 임상 데이터가 아직 많지 않으므로, 처음엔 소량으로 시작하고 자외선차단제와 함께 쓰는 편이 권장돼요.',array['niacinamide','hyaluronic-acid','licochalcone']::text[],'{}'::text[],array['pigmentation']::text[],'Mann T et al., J Invest Dermatol 2018; Arrowitz C et al., J Invest Dermatol 2019','moderate','2026-07-15',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('glutathione','글루타치온','Glutathione',array['tone','antioxidant']::text[],'rose','우리 몸에도 있는 트리펩타이드 항산화 물질이에요. 톤 케어·항산화 제품에 배합되곤 해요.','글루타치온은 글루탐산·시스테인·글리신으로 이뤄진 트리펩타이드로, 세포 내 대표적인 항산화 물질이에요. 티로시나아제 활성을 낮추고 유멜라닌 대신 페오멜라닌 생성 쪽으로 기울게 한다는 기전이 제안돼 있으나, 국소 도포 시 피부 투과가 낮아 화장품에서의 근거는 아직 제한적이에요. 2% 국소 제형에서 멜라닌 지수가 낮아졌다는 소규모 연구가 있고, 산화에 약해 제형 안정화가 중요해요. 자극이 낮아 비타민C 유도체, 나이아신아마이드와 함께 배합하기 무난해요.',array['niacinamide','ascorbyl-glucoside','tocopherol']::text[],'{}'::text[],array['dullness','pigmentation']::text[],'Watanabe F et al., Clin Cosmet Investig Dermatol 2014; Sonthalia S et al., Indian J Dermatol Venereol Leprol 2016','limited','2026-07-15','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('rice-extract','쌀추출물','Oryza Sativa (Rice) Extract',array['tone','hydration']::text[],'rose','쌀에서 얻는 추출물로, 보습과 화사한 톤 연출 목적의 제품에 오래 쓰여 온 성분이에요.','쌀추출물에는 감마오리자놀, 페룰릭애씨드, 이노시톨, 비타민 B군, 아미노산 등이 들어 있어요. 감마오리자놀과 페룰릭애씨드는 항산화 작용이, 쌀 발효물이나 쌀겨 유래 성분은 티로시나아제 억제와 보습 보조가 실험실 수준에서 보고돼 있어요. 다만 추출 부위(쌀알·쌀겨·발효물)와 방식에 따라 조성이 크게 달라 제품 간 체감 차이가 있을 수 있고, 사람 대상 임상 근거는 제한적이에요. 자극이 낮은 편이라 나이아신아마이드, 히알루론산과 함께 아침·저녁 모두 쓰기 무난해요.',array['niacinamide','hyaluronic-acid','galactomyces','glycerin']::text[],'{}'::text[],array['dullness','dryness']::text[],'CIR Expert Panel Final Report (Oryza Sativa); 대한화장품협회 성분사전','limited','2026-07-22','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('yuja','유자추출물','Citrus Junos Fruit Extract',array['tone','antioxidant']::text[],'rose','유자 열매에서 얻는 추출물이에요. 비타민C와 플라보노이드가 있어 톤·항산화 제품에 자주 쓰여요.','유자추출물에는 아스코빅애씨드, 헤스페리딘·나린긴 같은 플라보노이드, 시트릭애씨드 등이 들어 있어 항산화와 톤 케어 목적의 제품에 배합돼요. 세포 실험에서 항산화와 티로시나아제 억제가 보고돼 있지만, 화장품 농도의 사람 대상 근거는 제한적이에요. 감귤류 추출물이라 과피 유래 정유 성분이 일부 포함될 수 있고, 향에 민감한 편이라면 반응이 다를 수 있어요. 나이아신아마이드, 히알루론산과 조합이 무난하고, 아침 사용 시 자외선차단제와 함께 쓰는 편이 권장돼요.',array['niacinamide','hyaluronic-acid','green-tea']::text[],'{}'::text[],array['dullness']::text[],'대한화장품협회 성분사전; 화장품 성분학 교과서(Draelos)','limited','2026-07-22','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('pearl','진주추출물','Pearl Extract',array['tone','hydration']::text[],'rose','진주를 곱게 갈거나 가수분해해 얻는 성분이에요. 화사한 톤 연출과 보습 목적으로 배합돼요.','진주추출물은 탄산칼슘을 주성분으로 하고, 콘키올린이라는 단백질과 여기서 나온 아미노산·미네랄을 소량 포함해요. 가수분해 콘키올린이 보습과 컨디셔닝에 쓰이고, 세포 실험에서 항산화와 티로시나아제 억제가 보고된 바 있지만 화장품 농도에서의 사람 대상 근거는 제한적이에요. 제품에서 느껴지는 즉각적인 광택은 함께 배합된 진주 광택 안료(마이카 등)에 의한 경우가 많아요. 자극이 낮은 편이라 나이아신아마이드, 히알루론산과 함께 쓰기 무난해요.',array['niacinamide','hyaluronic-acid','glycerin']::text[],'{}'::text[],array['dullness']::text[],'CIR Expert Panel (Hydrolyzed Conchiolin Protein); 대한화장품협회 성분사전','limited','2026-07-22','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('hyaluronic-acid','히알루론산','Sodium Hyaluronate',array['hydration']::text[],'sky','자기 무게의 수백 배 수분을 붙잡는 대표적인 보습 성분이에요. 분자 크기에 따라 작용하는 층이 달라요.','히알루론산의 나트륨염으로, 각질층 표면에서 물을 끌어당겨 유지하는 휴멕턴트예요. 고분자는 피부 표면에 수분막을 만들고, 저분자는 각질층 안쪽까지 스며드는 것으로 소개되어 여러 분자량을 함께 배합하는 설계가 흔해요. 대체로 0.1~2% 정도로 배합되며, 습도가 낮은 환경에서는 오히려 피부 수분을 빼앗길 수 있어 위에 크림이나 오일로 덮어주는 편이 권장돼요. pH 제약이 적고 자극이 낮아 거의 모든 활성 성분과 조합할 수 있고, 아침·저녁 모두 사용할 수 있어요.',array['ceramide','niacinamide','panthenol','glycerin']::text[],'{}'::text[],array['dryness','texture']::text[],'Pavicic T et al., J Drugs Dermatol 2011; CIR Expert Panel Final Report (Hyaluronic Acid)','high','2026-08-25','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('glycerin','글리세린','Glycerin',array['hydration']::text[],'sky','가장 널리 쓰이는 보습 성분 중 하나예요. 대부분의 스킨케어 제품에 기본적으로 들어 있어요.','글리세린은 3개의 하이드록시기를 가진 작은 다가알코올로, 주변에서 수분을 끌어당겨 각질층에 붙잡아 두는 휴멕턴트예요. 각질층의 아쿠아포린-3 경로를 통해 이동하고, 각질 세포 사이 지질의 결정 상태를 유지해 건조 환경에서도 유연성을 돕는 것으로 보고돼요. 보통 2~10% 정도로 배합되고, 고농도에서는 끈적임이 생길 수 있어요. 수십 년간 사용된 성분으로 자극 보고가 드물고, 히알루론산, 세라마이드, 판테놀 등 어떤 성분과도 조합하기 무난해요.',array['hyaluronic-acid','ceramide','panthenol','betaine']::text[],'{}'::text[],array['dryness']::text[],'Fluhr JW et al., Br J Dermatol 2008; CIR Expert Panel Final Report (Glycerin)','high','2026-08-25','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('betaine','베타인','Betaine',array['hydration','soothing']::text[],'sky','사탕무 등에서 얻는 아미노산 유도체예요. 순한 보습·컨디셔닝 성분으로 토너나 앰플에 자주 들어가요.','베타인(트리메틸글리신)은 세포가 삼투압 변화에 맞서 수분 균형을 유지할 때 쓰는 삼투 보호 물질이에요. 물 분자와 잘 결합해 각질층 수분 유지를 돕고, 계면활성제로 인한 자극감을 낮추는 보조 성분으로도 쓰여요. 보통 1~5% 정도로 배합되고 끈적임이 적어 가벼운 제형에 넣기 쉬워요. 자극 보고가 드문 편이라 민감한 시기의 제품에도 자주 들어가며, 히알루론산, 글리세린, 판테놀과 조합이 무난해요. pH 제약이 적어 아침·저녁 모두 사용할 수 있어요.',array['hyaluronic-acid','glycerin','panthenol','allantoin']::text[],'{}'::text[],array['dryness','barrier']::text[],'CIR Expert Panel Final Report (Betaine); 대한화장품협회 성분사전','moderate','2026-08-25','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('beta-glucan','베타글루칸','Beta-Glucan',array['hydration','soothing']::text[],'sky','귀리·효모 등에서 얻는 다당류예요. 수분 유지와 진정 목적으로 스킨케어에 자주 활용돼요.','베타글루칸은 포도당이 β-결합으로 길게 이어진 다당류로, 피부 표면에 얇은 수분막을 만들어 건조를 줄이고, 면역세포 수용체(덱틴-1 등)와 상호작용해 자극 반응을 완화하는 것으로 소개돼요. 귀리 유래(β-1,3/1,4)와 효모 유래(β-1,3/1,6)는 구조가 조금 다르고, 보통 0.1~2% 정도로 배합돼요. 분자량이 커서 흡수보다는 표면 작용 위주로 이해되고 있어요. 자극이 낮은 편이라 히알루론산, 판테놀, 병풀추출물과 조합하기 무난하고, 아침·저녁 모두 사용할 수 있어요.',array['hyaluronic-acid','panthenol','centella','ceramide']::text[],'{}'::text[],array['dryness','barrier']::text[],'Du B et al., Int J Cosmet Sci 2014; Pillai R et al., Int J Cosmet Sci 2005','moderate','2026-08-18','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('trehalose','트레할로스','Trehalose',array['hydration']::text[],'sky','건조 환경에서 생물이 수분을 지킬 때 쓰는 당이에요. 스킨케어에서는 순한 보습 보조 성분으로 쓰여요.','트레할로스는 포도당 두 분자가 결합한 이당류로, 부활초처럼 극한 건조를 견디는 생물이 세포 구조를 보호할 때 축적하는 물질이에요. 물 분자와 수소결합을 이뤄 각질층 수분 유지를 돕고, 단백질과 지질막의 구조를 안정화하는 것으로 보고돼요. 보통 0.5~3% 정도로 배합되며 끈적임이 적고 pH 제약이 거의 없어요. 화장품에서의 사람 대상 근거는 제한적이지만 자극 보고가 드물어 히알루론산, 글리세린, 베타인 등과 함께 아침·저녁 모두 쓰기 무난해요.',array['hyaluronic-acid','glycerin','betaine']::text[],'{}'::text[],array['dryness']::text[],'CIR Expert Panel Final Report (Trehalose); Ohtake S & Wang YJ, J Pharm Sci 2011','limited','2026-08-18','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('sodium-pca','소듐PCA','Sodium PCA',array['hydration']::text[],'sky','피부 천연보습인자(NMF)의 주요 구성 성분이에요. 각질층 수분을 붙잡는 순한 보습 성분이에요.','소듐PCA는 피롤리돈카복실산의 나트륨염으로, 각질층의 천연보습인자(NMF) 중 약 12%를 차지하는 물질이에요. 피부 안에서는 필라그린이 분해되며 만들어지고, 강한 수분 결합력으로 각질층 유연성을 유지하는 데 관여해요. 화장품에는 보통 0.5~2.5% 정도로 배합되고 끈적임이 적어 토너·에센스에 넣기 쉬워요. 글리세린, 히알루론산, 우레아 같은 다른 NMF 계열 보습제와 함께 배합하는 처방이 흔하며, pH 제약이 적어 아침·저녁 모두 사용할 수 있어요.',array['glycerin','hyaluronic-acid','urea','betaine']::text[],'{}'::text[],array['dryness']::text[],'CIR Expert Panel Final Report (PCA and Sodium PCA); Rawlings AV & Harding CR, Dermatol Ther 2004','moderate','2026-08-18','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('urea','우레아','Urea',array['hydration','exfoliation']::text[],'sky','피부 천연보습인자에도 들어 있는 성분이에요. 저농도는 보습, 고농도는 각질 연화에 쓰여요.','우레아(요소)는 천연보습인자(NMF)의 약 7%를 차지하는 물질로, 농도에 따라 역할이 달라져요. 2~10% 정도에서는 각질층 수분 결합을 도와 보습제로, 10% 이상에서는 각질 단백질의 결합을 느슨하게 해 거칠어진 각질을 부드럽게 하는 각질 연화제로 쓰여요. 자극이 낮은 편이지만 고농도는 상처나 갈라진 부위에 따끔할 수 있고, 제형 pH에 따라 암모니아로 분해되기 쉬워 안정화 기술이 중요해요. 세라마이드, 락틱애씨드와 함께 배합하는 처방이 흔하고, 아침·저녁 모두 사용할 수 있어요.',array['ceramide','lactic-acid','glycerin','sodium-pca']::text[],'{}'::text[],array['dryness','texture']::text[],'Celleno L, Dermatol Ther 2018; Pan M et al., Adv Dermatol Allergol 2013','high','2026-08-10','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('polyglutamic-acid','폴리글루타믹애씨드','Polyglutamic Acid',array['hydration']::text[],'sky','청국장의 끈적한 실에서 알려진 보습 성분이에요. 히알루론산과 함께 배합되는 경우가 많아요.','폴리글루타믹애씨드(γ-PGA)는 글루탐산이 길게 이어진 고분자로, 바실러스 발효 과정에서 만들어져요. 분자량이 커서 피부 표면에 수분막을 형성하고, 실험실 수준에서는 히알루론산보다 수분 결합력이 높다고 소개되기도 해요. 또한 히알루론산을 분해하는 히알루로니다아제를 억제한다는 보고가 있어 두 성분을 함께 배합하는 처방이 흔해요. 보통 0.1~1% 정도로 배합되고 pH 제약이 적어요. 사람 대상 근거는 아직 제한적이지만 자극 보고가 드물어 아침·저녁 모두 쓰기 무난해요.',array['hyaluronic-acid','glycerin','ceramide']::text[],'{}'::text[],array['dryness']::text[],'Ben-Zur N & Goldman DM, Cosmet Toiletries 2007; 대한화장품협회 성분사전','limited','2026-08-10','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('aloe','알로에베라잎추출물','Aloe Barbadensis Leaf Extract',array['hydration','soothing']::text[],'sky','알로에 잎에서 얻는 추출물이에요. 수분 공급과 진정 목적의 젤·토너에 오래 쓰여 온 성분이에요.','알로에베라잎추출물에는 아세만난 같은 다당류, 비타민, 아미노산, 효소 등이 들어 있어요. 다당류는 피부 표면에 수분막을 만들어 보습감을 주고, 일부 성분이 염증 관련 신호를 완화한다는 보고가 있어 자외선 노출 후 진정용 제품에 자주 쓰여요. 다만 제품 표기의 알로에 함량은 희석 정도가 제각각이라 체감이 다를 수 있고, 잎 껍질에 있는 알로인 성분은 자극 가능성이 있어 정제된 원료를 쓰는 편이 일반적이에요. 자극 보고는 드문 편이지만 백합과 식물 알레르기가 있다면 주의가 필요해요.',array['hyaluronic-acid','panthenol','centella','allantoin']::text[],'{}'::text[],array['dryness','breakout']::text[],'CIR Expert Panel Final Report (Aloe); Surjushe A et al., Indian J Dermatol 2008','moderate','2026-08-10','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('snail-mucin','달팽이점액여과물','Snail Secretion Filtrate',array['hydration','renewal']::text[],'sky','달팽이 점액을 여과한 성분이에요. 보습과 매끈한 결 연출 목적의 K-뷰티 제품에 오래 쓰여 왔어요.','달팽이점액여과물은 글리코사미노글리칸, 알란토인, 글라이콜릭애씨드, 펩타이드, 항균 단백질 등이 섞인 복합 원료예요. 점액 다당류가 피부 표면에 수분막을 만들고, 소규모 연구에서 결과 잔주름 관련 지표 개선이 보고돼 리뉴얼 목적으로도 소개되지만 사람 대상 임상 근거는 아직 제한적이에요. 원료 채취·정제 방식과 함량이 제품마다 크게 달라 체감 차이가 있을 수 있어요. 자극이 낮은 편이라 히알루론산, 나이아신아마이드, 펩타이드와 함께 쓰기 무난하고, 연체동물 알레르기가 있다면 주의가 필요해요.',array['hyaluronic-acid','niacinamide','peptides','panthenol']::text[],'{}'::text[],array['texture','dryness']::text[],'Fabi SG et al., J Drugs Dermatol 2013; Tribó-Boixareu MJ et al., Cosmet Dermatol 2009','limited','2026-08-03','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('honey','꿀추출물','Honey Extract',array['hydration','soothing']::text[],'sky','꿀에서 얻는 추출물로, 당류와 소량의 유기산이 있어 보습과 진정 목적으로 배합돼요.','꿀추출물은 과당·포도당 같은 당류가 대부분이고, 글루코닉애씨드 등 유기산, 아미노산, 폴리페놀, 소량의 효소를 포함해요. 당류가 수분을 끌어당기는 휴멕턴트 역할을 하고, 폴리페놀은 항산화, 과산화수소 생성 효소와 낮은 pH는 실험실 수준에서 항균 작용이 보고돼 있어요. 다만 화장품 농도에서의 사람 대상 근거는 제한적이고, 원산지·꽃 종류에 따라 조성이 달라요. 벌 유래 성분(프로폴리스, 로열젤리 등)에 알레르기가 있다면 주의가 필요하고, 히알루론산, 글리세린, 프로폴리스와 함께 배합하는 처방이 흔해요.',array['hyaluronic-acid','glycerin','propolis']::text[],'{}'::text[],array['dryness']::text[],'Burlando B & Cornara L, J Cosmet Dermatol 2013; CIR Expert Panel (Honey)','limited','2026-08-03','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('thermal-water','온천수','Thermal Spring Water',array['hydration','soothing']::text[],'sky','특정 온천에서 길어 올린 미네랄 함유 물이에요. 미스트 형태로 진정·수분 보충 목적에 자주 쓰여요.','온천수는 원천에 따라 셀레늄, 규소, 칼슘, 마그네슘, 스트론튬 등 미네랄 조성이 달라요. 일부 원천은 자극이 있는 피부에서 가려움·홍조 관련 지표를 낮췄다는 임상 연구가 있고, 셀레늄이나 스트론튬 같은 특정 이온의 항산화·감각 완화 작용이 제안돼 있어요. 다만 보습력 자체는 낮아 뿌린 뒤 그대로 두면 증발하며 건조해질 수 있어, 가볍게 닦거나 크림으로 덮어주는 편이 권장돼요. 자극이 매우 낮은 편이라 어떤 성분과도 조합할 수 있고, 온천마다 미네랄 차이가 커서 브랜드별 체감이 다를 수 있어요.',array['hyaluronic-acid','panthenol','ceramide','glycerin']::text[],'{}'::text[],array['barrier','dryness']::text[],'Seité S, Clin Cosmet Investig Dermatol 2013; Merial-Kieny C et al., J Eur Acad Dermatol Venereol 2011','moderate','2026-08-03','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('collagen','하이드롤라이즈드콜라겐','Hydrolyzed Collagen',array['hydration','firming']::text[],'sky','콜라겐을 작게 쪼갠 펩타이드 형태예요. 피부 속 콜라겐이 늘어나기보다 표면 보습에 주로 작용해요.','하이드롤라이즈드콜라겐은 어류나 돼지 등에서 얻은 콜라겐을 효소로 분해해 분자량을 낮춘 펩타이드 혼합물이에요. 분자가 커서 각질층을 통과해 진피 콜라겐을 직접 보충하지는 못하는 것으로 이해되고, 대신 피부 표면에 수분막을 만들어 보습감과 매끈한 촉감을 주는 필름 형성 성분으로 작용해요. 보통 0.1~3% 정도로 배합되고 자극 보고가 드물어요. 탄력 관련 근거는 국소 도포보다 경구 섭취 연구가 많으며, 화장품에서는 히알루론산, 글리세린과 함께 보습 목적으로 이해하는 편이 적절해요.',array['hyaluronic-acid','glycerin','peptides']::text[],'{}'::text[],array['dryness','firming']::text[],'CIR Expert Panel Final Report (Hydrolyzed Collagen); Draelos ZD, Cosmetic Dermatology (2015)','limited','2026-07-30','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('birch-sap','자작나무수액','Betula Platyphylla Japonica Juice',array['hydration']::text[],'sky','이른 봄 자작나무에서 채취하는 수액이에요. 정제수 대신 넣어 가벼운 수분감을 주는 성분이에요.','자작나무수액은 포도당·과당 같은 당류, 아미노산, 칼륨·칼슘·마그네슘 등 미네랄, 소량의 유기산과 폴리페놀을 포함한 묽은 수용액이에요. 스킨케어에서는 정제수를 대신해 베이스로 쓰이며, 당류와 미네랄이 가벼운 보습감을 더하는 것으로 소개돼요. 세포 실험에서 항산화나 보습 관련 지표가 보고된 바 있으나 사람 대상 근거는 제한적이에요. 채취 시기와 정제 방식에 따라 조성이 달라지고, 자작나무 꽃가루 알레르기가 있다면 주의가 필요해요. 히알루론산, 베타인과 함께 아침·저녁 모두 쓰기 무난해요.',array['hyaluronic-acid','betaine','glycerin']::text[],'{}'::text[],array['dryness']::text[],'대한화장품협회 성분사전; 화장품 성분학 교과서(Draelos)','limited','2026-07-30','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('bamboo-water','대나무수','Bambusa Vulgaris Water',array['hydration']::text[],'sky','대나무 줄기에서 얻는 수액이에요. 정제수 대신 넣어 가벼운 수분감과 미네랄을 더하는 성분이에요.','대나무수는 대나무 줄기 속 수액을 정제한 것으로, 규소를 비롯한 미네랄, 소량의 아미노산·당류·폴리페놀을 포함해요. 스킨케어에서는 정제수를 대신하는 베이스로 쓰이며, 가벼운 보습감을 주고 규소 성분이 피부 컨디셔닝에 도움이 된다고 소개돼요. 대나무 유래 추출물의 항산화·항염 작용이 실험실 수준에서 보고돼 있으나, 화장품 농도에서의 사람 대상 근거는 제한적이에요. 자극 보고가 드물고 pH 제약이 없어 히알루론산, 글리세린, 판테놀과 함께 아침·저녁 모두 쓰기 무난해요.',array['hyaluronic-acid','glycerin','panthenol']::text[],'{}'::text[],array['dryness']::text[],'대한화장품협회 성분사전; 화장품 성분학 교과서(Draelos)','limited','2026-07-30','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('ceramide','세라마이드','Ceramide NP',array['barrier','hydration']::text[],'mint','각질층에서 벽돌 사이의 시멘트 같은 역할을 하는 지질 성분이에요. 장벽 관련 제품에 자주 등장해요.','세라마이드는 각질세포 사이 지질의 약 50%를 차지하는 스핑고지질로, 콜레스테롤·지방산과 함께 층상 구조를 이뤄 수분 증발을 막고 외부 자극을 차단하는 데 관여해요. 건조하거나 민감한 피부에서는 세라마이드 비율이 낮다는 보고가 있어 이를 보충하는 개념으로 배합돼요. NP, AP, EOP 등 종류가 다양하고, 세라마이드:콜레스테롤:지방산을 약 3:1:1 비율로 맞춘 처방이 장벽 지질 구조 형성에 유리하다고 보고돼요. 자극이 낮아 어떤 성분과도 조합할 수 있고, 레티놀·산 계열 사용 시 함께 쓰는 완충 역할로도 자주 언급돼요.',array['cholesterol','fatty-acids','hyaluronic-acid','niacinamide']::text[],'{}'::text[],array['barrier','dryness']::text[],'Man MQ et al., Arch Dermatol 1993; Coderch L et al., Am J Clin Dermatol 2003','high','2026-08-28','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('cholesterol','콜레스테롤','Cholesterol',array['barrier']::text[],'mint','각질층 지질의 한 축을 이루는 성분이에요. 세라마이드·지방산과 함께 장벽 처방에 들어가요.','콜레스테롤은 세라마이드, 유리지방산과 함께 각질층 세포간 지질의 3대 구성 요소로, 지질 층상 구조의 유연성과 밀도를 조절하는 역할을 해요. 나이가 들수록 각질층 콜레스테롤 합성이 줄어든다는 보고가 있어, 성숙한 피부의 장벽 처방에서는 콜레스테롤 비율을 높인 배합이 소개되기도 해요. 세 지질 중 한 가지만 넣으면 오히려 장벽 회복이 늦어질 수 있어 균형 잡힌 비율(예: 3:1:1)로 배합하는 편이 권장돼요. 자극 보고가 드물고 크림·밤 제형에서 세라마이드, 스쿠알란과 함께 쓰기 무난해요.',array['ceramide','fatty-acids','squalane','panthenol']::text[],'{}'::text[],array['barrier','dryness']::text[],'Zettersten EM et al., J Am Acad Dermatol 1997; Man MQ et al., Arch Dermatol 1993','high','2026-08-28','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('fatty-acids','지방산(리놀레익애씨드)','Linoleic Acid',array['barrier']::text[],'mint','해바라기·홍화 오일에 풍부한 오메가-6 지방산이에요. 장벽 지질을 보충하는 처방에 자주 쓰여요.','리놀레익애씨드는 각질층 세라마이드 1(EOS)의 구성 요소로 들어가는 필수지방산이에요. 피부에 리놀레익애씨드가 부족하면 장벽 기능이 떨어지고 수분 손실이 늘어난다는 보고가 있고, 피지 속 리놀레익애씨드 비율이 낮은 경우 모공 막힘과 연관된다는 관찰도 있어 트러블 경향 피부의 오일 선택 기준으로 자주 언급돼요. 화장품에서는 순수 지방산보다 해바라기씨오일, 로즈힙오일 등 식물 오일 형태로 배합되는 경우가 많아요. 산화되기 쉬워 토코페롤과 함께 배합하는 처방이 흔하고, 세라마이드·콜레스테롤과 조합이 무난해요.',array['ceramide','cholesterol','tocopherol','sunflower-oil']::text[],'{}'::text[],array['barrier','dryness']::text[],'Elias PM et al., J Invest Dermatol 1980; Darmstadt GL et al., Acta Paediatr 2002','high','2026-08-28','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('squalane','스쿠알란','Squalane',array['barrier','hydration']::text[],'mint','피지에도 있는 스쿠알렌을 안정화한 오일이에요. 가볍고 산화에 강해 장벽·보습 제품에 널리 쓰여요.','스쿠알란은 스쿠알렌에 수소를 첨가해 산화 안정성을 높인 포화 탄화수소예요. 예전엔 상어 간유에서 얻었지만 지금은 올리브·사탕수수 유래가 대부분이에요. 피지 성분과 구조가 유사해 피부에 잘 스며들고, 각질층 지질 사이를 채워 수분 증발을 줄이는 폐색 보습제 역할을 해요. 끈적임이 적고 모공을 잘 막지 않는 편으로 알려져 지성 피부의 오일로도 자주 소개돼요. 산화가 잘 되지 않아 변질 우려가 낮고, 세라마이드, 레티놀, 히알루론산 등 어떤 성분과도 조합하기 무난해 루틴 마지막 단계나 크림에 섞어 쓰는 방식이 흔해요.',array['ceramide','retinol','hyaluronic-acid','cholesterol']::text[],'{}'::text[],array['dryness','barrier']::text[],'Huang ZR et al., Molecules 2009; CIR Expert Panel Final Report (Squalane)','moderate','2026-08-22','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('panthenol','판테놀','Panthenol',array['barrier','soothing','hydration']::text[],'mint','프로비타민 B5로 불리는 성분이에요. 진정·보습·장벽 관리 목적으로 스킨케어에 흔히 배합돼요.','판테놀은 피부에 흡수된 뒤 판토텐산(비타민 B5)으로 전환되어 코엔자임A 합성에 관여하고, 각질형성세포의 증식과 지질 합성을 돕는 것으로 알려져 있어요. 휴멕턴트로서 각질층 수분을 붙잡고, 경표피수분손실(TEWL)을 낮추며 자극 후 붉어짐을 완화했다는 임상 보고가 있어요. 보통 1~5% 정도로 배합되고 D-판테놀(덱스판테놀) 형태가 활성이 있어요. pH 제약이 적고 자극 보고가 드물어 레티놀, 산 계열과 함께 쓰는 완충 성분으로 자주 언급되며, 아침·저녁 모두 사용할 수 있어요.',array['ceramide','centella','hyaluronic-acid','allantoin']::text[],'{}'::text[],array['barrier','dryness','breakout']::text[],'Ebner F et al., Am J Clin Dermatol 2002; Proksch E et al., J Dermatolog Treat 2017','high','2026-08-22','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('shea-butter','시어버터','Butyrospermum Parkii (Shea) Butter',array['barrier']::text[],'mint','시어나무 열매에서 얻는 식물성 버터예요. 건조한 피부를 덮어주는 크림·밤에 자주 쓰여요.','시어버터는 올레익·스테아릭애씨드 같은 지방산이 대부분이고, 트리테르펜 알코올(루페올, 아미린), 신남산 에스터, 토코페롤 등 비누화되지 않는 성분이 다른 식물 유지보다 많은 편이에요. 지방산이 피부 표면에 막을 만들어 수분 증발을 줄이고, 비누화되지 않는 성분은 항산화와 염증 신호 완화가 실험실 수준에서 보고돼 있어요. 무거운 편이라 지성 피부에서는 답답할 수 있고, 얼굴보다 몸에 쓰이는 경우가 많아요. 정제 정도에 따라 향과 색이 달라지며, 세라마이드, 스쿠알란과 함께 루틴 마지막 단계에 쓰기 무난해요.',array['ceramide','squalane','glycerin','panthenol']::text[],'{}'::text[],array['dryness']::text[],'Akihisa T et al., J Oleo Sci 2010; CIR Expert Panel Final Report (Butyrospermum Parkii)','moderate','2026-08-22','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('petrolatum','페트롤라툼','Petrolatum',array['barrier']::text[],'mint','석유에서 정제한 반고체 탄화수소예요. 수분 증발을 막는 힘이 가장 강한 편에 속하는 폐색 보습제예요.','페트롤라툼(바셀린)은 경표피수분손실을 최대 98%까지 줄인다고 보고된 대표적인 폐색제로, 피부 표면에 막을 만들어 수분이 빠져나가는 것을 막아요. 각질층 지질 사이로도 일부 스며들어 장벽 회복을 돕는다는 연구가 있고, 접촉 알레르기 보고가 극히 드물어 피부과 시술 후 관리에도 널리 쓰여요. 그 자체가 수분을 공급하지는 않으므로 수분 제품 위에 얇게 덮는 방식(슬러깅)이 소개돼요. 무겁고 광택이 나 지성 피부는 부담스러울 수 있고, 트러블 경향이라면 얼굴 전체보다 건조한 부위에만 쓰는 편이 권장돼요.',array['hyaluronic-acid','glycerin','ceramide']::text[],'{}'::text[],array['dryness','barrier']::text[],'Ghadially R et al., J Am Acad Dermatol 1992; Draelos ZD, Cosmetic Dermatology (2015)','high','2026-08-15','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('dimethicone','다이메티콘','Dimethicone',array['barrier']::text[],'mint','가장 흔히 쓰이는 실리콘 오일이에요. 매끄러운 사용감과 수분 증발 억제 목적으로 배합돼요.','다이메티콘은 규소-산소 골격의 합성 고분자로, 피부 표면에 통기성 있는 막을 만들어 수분 증발을 줄이면서도 끈적임이 적은 것이 특징이에요. 페트롤라툼보다 폐색력은 낮지만 가볍고 매끄러워 로션·선크림·프라이머에 널리 쓰이고, 다른 성분의 자극감을 줄이는 보호막 역할도 해요. 분자가 커서 피부에 흡수되지 않고, 알레르기 보고가 드물어 시술 후 보호 크림에도 자주 배합돼요. 모공을 막는다는 우려가 자주 언급되지만 실리콘은 통기성이 있어 코메도 유발 가능성이 낮은 편으로 알려져 있고, 어떤 성분과도 조합할 수 있어요.',array['ceramide','glycerin','titanium-dioxide','zinc-oxide']::text[],'{}'::text[],array['barrier']::text[],'CIR Expert Panel Final Report (Dimethicone); Nair B, Int J Toxicol 2003','high','2026-08-15','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('ectoin','엑토인','Ectoin',array['barrier','soothing']::text[],'mint','사막·염호 미생물에서 발견된 보호 물질이에요. 최근 진정·장벽 라인에 자주 등장하는 성분이에요.','엑토인은 극한 환경에 사는 호염성 미생물이 삼투압과 건조에서 세포를 지키려고 만드는 아미노산 유도체예요. 물 분자를 강하게 붙잡아 세포와 지질막 주변에 수화층을 형성하고, 이를 통해 자외선·미세먼지 같은 외부 자극으로 인한 스트레스 신호를 완화한다는 기전이 제안돼 있어요. 0.5~2% 국소 도포에서 각질층 수분과 자극 관련 지표가 개선됐다는 임상 보고가 있어요. pH 제약이 적고 자극 보고가 드물어 판테놀, 세라마이드, 병풀추출물과 조합하기 무난하고, 아침·저녁 모두 사용할 수 있어요.',array['panthenol','ceramide','centella','hyaluronic-acid']::text[],'{}'::text[],array['barrier','dryness']::text[],'Graf R et al., Clin Dermatol 2008; Bownik A & Stępniewska Z, Pharmacol Rep 2016','moderate','2026-08-15','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('colloidal-oatmeal','콜로이달오트밀','Avena Sativa (Oat) Kernel Flour',array['barrier','soothing']::text[],'mint','귀리 알갱이를 곱게 간 성분이에요. 가렵고 건조한 피부의 진정 목적으로 오래 쓰여 왔어요.','콜로이달오트밀은 귀리를 통째로 미세하게 분쇄해 물에 고르게 퍼지도록 만든 것으로, 베타글루칸·전분·단백질·지질과 함께 아베난트라마이드라는 폴리페놀을 포함해요. 아베난트라마이드는 히스타민 방출과 염증 신호를 줄이는 것으로 보고돼 가려움 완화 목적에 쓰이고, 전분과 베타글루칸은 피부 표면에 보호막을 만들어 수분 유지를 도와요. 미국 FDA에서는 피부 보호제 성분으로 분류돼 있어요. 보통 1% 이상 배합되며, 귀리 알레르기가 있다면 주의가 필요해요. 세라마이드, 판테놀과 함께 민감한 시기의 크림에 자주 쓰여요.',array['ceramide','panthenol','beta-glucan','glycerin']::text[],'{}'::text[],array['barrier','dryness']::text[],'Reynertson KA et al., J Drugs Dermatol 2015; Sur R et al., Arch Dermatol Res 2008','high','2026-08-08','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('pea','팔미토일에탄올아마이드','Palmitoylethanolamide',array['barrier','soothing']::text[],'mint','우리 몸에서도 만들어지는 지방산 아마이드예요. 민감한 피부의 자극 완화 목적으로 배합되는 성분이에요.','팔미토일에탄올아마이드(PEA)는 몸 안에서 자연적으로 만들어지는 내인성 지질로, PPAR-α 수용체와 엔도카나비노이드 경로에 작용해 비만세포 활성과 염증 신호를 낮추는 것으로 알려져 있어요. 국소 도포 시 가려움·홍조 관련 지표를 개선했다는 임상 보고가 있고, 장벽 지질 보충 개념으로 크림에 배합돼요. 물에 잘 녹지 않아 유상에 넣거나 나노 분산 기술을 쓰기도 해요. 자극 보고가 드물어 세라마이드, 콜로이달오트밀, 판테놀과 함께 민감한 시기의 제품에 쓰이며, 아침·저녁 모두 사용할 수 있어요.',array['ceramide','colloidal-oatmeal','panthenol','ectoin']::text[],'{}'::text[],array['barrier']::text[],'Eberlein B et al., J Eur Acad Dermatol Venereol 2008; Petrosino S & Di Marzo V, Br J Pharmacol 2017','moderate','2026-08-08','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('mineral-oil','미네랄오일','Mineral Oil',array['barrier']::text[],'mint','석유에서 고도로 정제한 액상 탄화수소예요. 수분 증발을 막아주는 순한 폐색 보습제로 오래 쓰였어요.','미네랄오일은 탄소 15~40개 정도의 포화 탄화수소 혼합물로, 피부 표면에 얇은 막을 만들어 수분 증발을 줄이는 폐색 보습제예요. 피부에 거의 흡수되지 않고 산화되지 않아 변질 우려가 낮으며, 화장품용은 불순물을 제거한 고순도 등급이 쓰여요. 접촉 알레르기 보고가 극히 드물어 민감한 피부용 크림이나 클렌징 오일에 널리 배합되고, 코메도 유발 우려가 자주 언급되지만 정제된 화장품용 미네랄오일은 사람 대상 연구에서 모공 막힘 경향이 낮은 편으로 보고돼 있어요. 무거운 사용감이 부담스러운 지성 피부라면 양을 조절하는 편이 좋아요.',array['glycerin','ceramide','hyaluronic-acid']::text[],'{}'::text[],array['dryness']::text[],'Rawlings AV & Lombard KJ, Int J Cosmet Sci 2012; DiNardo JC, J Cosmet Dermatol 2005','high','2026-08-08','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('sunflower-oil','해바라기씨오일','Helianthus Annuus (Sunflower) Seed Oil',array['barrier']::text[],'mint','해바라기 씨에서 짠 오일이에요. 리놀레익애씨드가 풍부해 장벽 관리용 오일로 자주 소개돼요.','해바라기씨오일은 리놀레익애씨드가 60% 안팎으로 많은 오메가-6 계열 식물 오일이에요(고올레익 품종은 올레익애씨드가 주성분). 리놀레익애씨드는 각질층 세라마이드 합성에 쓰이고, 피부에 도포했을 때 경표피수분손실을 줄이며 장벽 회복을 도왔다는 연구가 있어요. 올리브오일과 달리 장벽 지표를 나쁘게 하지 않았다는 비교 연구가 있어 민감한 피부의 오일로 자주 언급돼요. 다만 불포화지방산이 많아 산패되기 쉬우므로 토코페롤이 함께 들어간 제품을 고르고 개봉 후 빨리 쓰는 편이 권장되며, 트러블 경향이라면 소량으로 시작하는 편이 좋아요.',array['tocopherol','ceramide','squalane','fatty-acids']::text[],'{}'::text[],array['dryness']::text[],'Danby SG et al., Pediatr Dermatol 2013; Darmstadt GL et al., Acta Paediatr 2002','moderate','2026-08-01','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('olive-oil','올리브오일','Olea Europaea (Olive) Fruit Oil',array['barrier']::text[],'mint','올리브 열매에서 짠 오일이에요. 올레익애씨드와 스쿠알렌이 많아 보습 제품에 오래 쓰였어요.','올리브오일은 올레익애씨드가 60~80%로 대부분이고, 스쿠알렌, 토코페롤, 폴리페놀(하이드록시티로솔 등)을 포함해요. 피부 표면에 막을 만들어 수분 증발을 줄이고, 폴리페놀은 항산화 작용이 실험실 수준에서 보고돼 있어요. 다만 올레익애씨드는 각질층 지질 배열을 흐트러뜨려 투과를 높이는 성질이 있어, 반복 도포했을 때 장벽 지표가 나빠졌다는 연구가 있어요. 그래서 얼굴보다 몸이나 클렌징 오일 용도로 쓰는 편이 무난하고, 민감하거나 트러블 경향이라면 리놀레익애씨드 비율이 높은 오일이 대안으로 언급돼요. 산패에 유의해 보관하세요.',array['tocopherol','squalane','shea-butter']::text[],'{}'::text[],array['dryness']::text[],'Danby SG et al., Pediatr Dermatol 2013; CIR Expert Panel Final Report (Olea Europaea)','moderate','2026-08-01','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('evening-primrose-oil','달맞이꽃오일','Oenothera Biennis (Evening Primrose) Oil',array['barrier']::text[],'mint','달맞이꽃 씨에서 짠 오일이에요. 감마리놀렌산(GLA)이 있어 건조한 피부용 오일로 자주 소개돼요.','달맞이꽃오일은 리놀레익애씨드가 약 70%, 감마리놀렌산(GLA)이 8~10% 정도 들어 있는 오메가-6 계열 오일이에요. GLA는 몸에서 항염 계열 프로스타글란딘의 전구체로 작용하는 것으로 알려져 있고, 국소 도포 시 각질층 수분과 탄력 관련 지표가 개선됐다는 소규모 연구가 있어요. 다만 아토피 관련 경구 섭취 연구는 결과가 엇갈려 근거가 제한적이에요. 불포화지방산이 많아 산패에 매우 취약하므로 토코페롤이 함께 든 제품을 고르고 냉암소에 보관하는 편이 권장돼요. 세라마이드, 스쿠알란과 함께 저녁 루틴 마지막에 쓰는 방식이 흔해요.',array['tocopherol','ceramide','squalane']::text[],'{}'::text[],array['dryness']::text[],'Bamford JT et al., Cochrane Database Syst Rev 2013; Muggli R, Int J Cosmet Sci 2005','limited','2026-08-01','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('jojoba-oil','호호바오일','Simmondsia Chinensis (Jojoba) Seed Oil',array['barrier','sebum']::text[],'mint','호호바 씨에서 얻는 액상 왁스예요. 피지와 구조가 비슷해 지성·건성 모두에 무난한 오일로 소개돼요.','호호바오일은 화학적으로 트리글리세라이드가 아니라 긴 사슬 지방산과 지방 알코올이 결합한 액상 왁스 에스터예요. 사람 피지의 왁스 에스터와 구조가 비슷해 피부에 잘 퍼지고 산화에 매우 강해 변질 우려가 낮아요. 피부 표면에 가벼운 막을 만들어 수분 증발을 줄이고, 유분이 많은 피부에서는 피지와 섞여 산뜻하게 마무리돼 피지 밸런스 개념으로 소개되지만 피지 분비 자체를 줄인다는 근거는 제한적이에요. 코메도 유발 가능성이 낮은 편으로 알려져 있고, 자극 보고가 드물어 스쿠알란, 세라마이드, 토코페롤과 함께 쓰기 무난해요.',array['squalane','ceramide','tocopherol']::text[],'{}'::text[],array['dryness']::text[],'Pazyar N et al., G Ital Dermatol Venereol 2013; CIR Expert Panel Final Report (Simmondsia Chinensis)','moderate','2026-07-25','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('camellia-oil','동백오일','Camellia Japonica Seed Oil',array['antioxidant','barrier']::text[],'gold','동백나무 씨에서 짠 오일이에요. 올레익애씨드와 폴리페놀이 있어 항산화·보습 목적으로 배합돼요.','동백오일은 올레익애씨드가 80% 안팎으로 매우 많고, 토코페롤, 스쿠알렌, 폴리페놀, 카멜리아사포닌 등을 소량 포함해요. 산화 안정성이 높은 편이고 피부 표면에 부드러운 막을 만들어 수분 증발을 줄이며, 폴리페놀의 항산화 작용이 실험실 수준에서 보고돼 있어요. 제주 등 한국·일본에서 머릿결과 피부 손질에 오래 쓰여 온 전통 오일이에요. 올레익애씨드 비율이 높아 장벽이 약해진 상태에서는 투과를 높일 수 있으니 소량으로 시작하고, 리놀레익애씨드 계열 오일이나 토코페롤과 섞어 저녁 루틴 마지막에 쓰는 방식이 흔해요.',array['tocopherol','squalane','sunflower-oil']::text[],'{}'::text[],array['dryness']::text[],'대한화장품협회 성분사전; Lee CP & Yen GC, J Agric Food Chem 2006','limited','2026-07-25','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('lactobacillus','락토바실러스발효물','Lactobacillus Ferment',array['barrier','soothing']::text[],'mint','유산균을 배양해 얻은 발효물이에요. 피부 미생물 균형과 장벽 관리 개념으로 최근 자주 쓰여요.','락토바실러스발효물은 유산균 배양액에서 균체를 걸러내거나 용해한 것으로, 젖산·펩타이드·다당류·박테리오신 같은 대사산물을 포함해요. 살아 있는 균이 아니라 포스트바이오틱스 개념으로 배합되며, 실험실 수준에서 피부 상재균 중 트러블 관련 균의 성장을 억제하고 각질형성세포의 장벽 단백질 발현을 높였다는 보고가 있어요. 다만 사람 대상 임상 근거는 아직 제한적이고, 균주와 배양 조건에 따라 조성이 달라 제품 간 차이가 커요. 자극 보고가 드물어 세라마이드, 판테놀, 비피다발효용해물과 함께 아침·저녁 모두 쓰기 무난해요.',array['ceramide','panthenol','bifida','beta-glucan']::text[],'{}'::text[],array['barrier','breakout']::text[],'Lew LC & Liong MT, J Appl Microbiol 2013; CIR Expert Panel (Lactobacillus Ferment)','limited','2026-07-25','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('centella','병풀추출물','Centella Asiatica Extract',array['soothing','barrier']::text[],'mint','흔히 시카라고 부르는 병풀 추출물이에요. 진정과 장벽 관리 목적의 제품에 널리 쓰여요.','병풀추출물에는 마데카소사이드, 아시아티코사이드, 마데카식애씨드, 아시아틱애씨드 네 가지 트리테르펜이 주요 활성 성분으로 들어 있어요. 이 성분들은 콜라겐 합성 촉진과 염증 신호 완화가 보고돼 있고, 국소 도포 시 홍조·자극 관련 지표 개선과 장벽 회복 보조가 임상에서 관찰됐어요. 추출물 기준으로는 함량 표준화 여부에 따라 체감이 달라지고, TECA처럼 활성 성분을 정제한 원료가 쓰이기도 해요. 자극 보고가 드물어 레티놀·산 계열과 함께 쓰는 완충 성분으로 자주 언급되며, 판테놀, 세라마이드, 나이아신아마이드와 조합이 무난해요.',array['panthenol','ceramide','niacinamide','madecassoside']::text[],'{}'::text[],array['breakout','barrier']::text[],'Bylka W et al., Postepy Dermatol Alergol 2013; Ratz-Łyko A et al., Indian J Pharm Sci 2016','moderate','2026-08-30','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('madecassoside','마데카소사이드','Madecassoside',array['soothing','barrier']::text[],'mint','병풀에서 정제한 대표 활성 성분이에요. 진정 라인에서 시카의 핵심 성분으로 자주 소개돼요.','마데카소사이드는 병풀의 트리테르펜 사포닌 중 하나로, 추출물 대신 순도 높은 단일 성분으로 배합해 함량을 표준화할 수 있다는 장점이 있어요. 실험실과 동물 연구에서 염증 관련 사이토카인을 낮추고 콜라겐 합성과 상처 부위 재생을 도왔다는 보고가 있고, 사람 대상 연구에서는 비타민C와 함께 쓴 제형이 탄력·주름 관련 지표를 개선했다는 결과가 있어요. 보통 0.1~1% 정도로 배합되고 자극 보고가 드물어요. 판테놀, 세라마이드와 조합이 무난하며, 레티놀이나 산 계열 사용 후 진정 단계로 쓰는 방식이 흔해요.',array['panthenol','ceramide','centella','ascorbic-acid']::text[],'{}'::text[],array['breakout','barrier']::text[],'Haftek M et al., Exp Dermatol 2008; Liu M et al., Planta Med 2008','moderate','2026-08-30','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('allantoin','알란토인','Allantoin',array['soothing']::text[],'mint','컴프리 뿌리에서 발견된 성분으로 지금은 합성해 써요. 진정과 각질 컨디셔닝 목적으로 널리 쓰여요.','알란토인은 요산 대사 산물인 작은 분자로, 각질층의 수분 유지와 각질 연화를 돕고 자극받은 피부를 진정시키는 목적으로 배합돼요. 정확한 기전은 충분히 밝혀지지 않았지만 세포 증식 촉진과 각질 제거 보조 작용이 제안돼 있고, 미국 FDA에서는 0.5~2% 농도의 피부 보호제로 분류돼 있어요. 물에 잘 녹고 pH 제약이 적어 토너·크림·마스크 등 거의 모든 제형에 들어가요. 수십 년간 사용되며 자극 보고가 드물어 판테놀, 병풀추출물, 세라마이드와 함께 민감한 시기의 제품에 자주 쓰이고, 아침·저녁 모두 사용할 수 있어요.',array['panthenol','centella','ceramide','betaine']::text[],'{}'::text[],array['barrier','breakout']::text[],'CIR Expert Panel Final Report (Allantoin); Becker LC et al., Int J Toxicol 2010','moderate','2026-08-30','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('bisabolol','비사보롤','Bisabolol',array['soothing']::text[],'mint','캐모마일 정유의 주요 성분이에요. 순한 진정 성분으로 민감 피부용 제품에 자주 들어가요.','알파-비사보롤은 캐모마일 꽃에서 얻거나 칸델라 나무 오일에서 분리한 세스퀴테르펜 알코올로, 염증 관련 효소(COX, 5-LOX)와 사이토카인 신호를 낮추는 것으로 보고돼 있어요. 다른 성분의 피부 투과를 높이는 성질이 있어 활성 성분과 함께 배합하기도 하고, 향료 성분으로 인한 자극감을 줄이는 목적으로도 쓰여요. 보통 0.1~1% 정도로 배합되며 지용성이라 유상에 들어가요. 정유가 아니라 정제된 단일 성분이라 향에 민감한 사람도 쓰기 무난한 편이고, 판테놀, 알란토인, 병풀추출물과 함께 진정 라인에 자주 쓰여요.',array['panthenol','allantoin','centella','chamomile']::text[],'{}'::text[],array['breakout','barrier']::text[],'Kamatou GPP & Viljoen AM, J Am Oil Chem Soc 2010; CIR Expert Panel Final Report (Bisabolol)','moderate','2026-08-27','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('houttuynia','어성초추출물','Houttuynia Cordata Extract',array['soothing','sebum']::text[],'mint','약모밀이라고도 하는 어성초 추출물이에요. 진정과 피지·트러블 관리 라인에 자주 등장해요.','어성초추출물에는 쿼세틴·쿼시트린·루틴 같은 플라보노이드와 데카노일아세트알데하이드 계열 성분이 들어 있어요. 실험실 연구에서 항산화, 염증 관련 사이토카인 억제, 트러블 관련 균의 성장 억제가 보고돼 있고, 한국 화장품에서 진정 토너·앰플의 대표 원료로 널리 쓰여요. 다만 사람 대상 임상 근거는 아직 제한적이고, 추출 방식에 따라 향과 성분 함량이 달라져요. 자극 보고가 드물어 판테놀, 병풀추출물, 나이아신아마이드와 함께 아침·저녁 모두 쓰기 무난하고, 유분이 많은 시기의 진정 단계로 자주 소개돼요.',array['panthenol','centella','niacinamide','allantoin']::text[],'{}'::text[],array['breakout','sebum']::text[],'Kim SK et al., J Ethnopharmacol 2001; 대한화장품협회 성분사전','limited','2026-08-27','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('mugwort','쑥추출물','Artemisia Princeps Leaf Extract',array['soothing']::text[],'mint','한국에서 오래 쓰여 온 쑥 잎 추출물이에요. 진정 목적의 에센스에 자주 쓰이지만 향 성분이 있어요.','쑥추출물에는 유파틸린, 자세오시딘 같은 플라보노이드와 클로로겐산 등 페놀산이 들어 있고, 실험실 연구에서 항산화와 염증 관련 신호 완화가 보고돼 있어요. 한국 화장품에서 진정 에센스의 대표 원료로 쓰이며, 자극받은 피부의 홍조 완화 목적으로 소개돼요. 다만 국화과 식물이라 정유 성분(시네올, 투존 등)이 함께 들어 있어 특유의 향이 있고, 국화과 알레르기(돼지풀, 캐모마일 등)가 있다면 반응이 나타날 수 있어요. 사람 대상 근거는 제한적이므로 처음엔 소량으로 시작하고, 판테놀, 병풀추출물과 함께 쓰는 조합이 흔해요.',array['panthenol','centella','allantoin']::text[],array['fragrance']::text[],array['breakout','barrier']::text[],'Abad MJ et al., Molecules 2012 (Artemisia review); 대한화장품협회 성분사전','limited','2026-08-27',array['fragrance']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('green-tea','녹차추출물','Camellia Sinensis Leaf Extract',array['antioxidant','soothing','sebum']::text[],'gold','녹차 잎에서 얻는 추출물이에요. 카테킨(EGCG)이 풍부해 항산화·피지·진정 목적으로 널리 쓰여요.','녹차추출물의 핵심은 에피갈로카테킨갈레이트(EGCG)를 비롯한 폴리페놀이에요. EGCG는 강한 항산화 작용과 함께 자외선으로 인한 염증 신호를 완화하고, 피지선 세포에서 지질 합성을 줄인다는 보고가 있어요. 3% 녹차 에멀전을 도포한 소규모 연구에서 피지 분비가 줄었다는 결과가 있고, 카페인과 탄닌 성분이 가벼운 수렴감을 줘 유분이 많은 피부의 토너에 자주 배합돼요. 카테킨은 산화되기 쉬워 갈변할 수 있으니 제형 안정화가 중요하고, 비타민C 유도체·나이아신아마이드와 함께 아침 항산화 단계로 쓰는 조합이 흔해요.',array['niacinamide','ascorbyl-glucoside','hyaluronic-acid','caffeine']::text[],'{}'::text[],array['sebum','breakout','dullness']::text[],'Mahmood T et al., Bosn J Basic Med Sci 2010; Katiyar SK, Curr Drug Targets Immune Endocr Metabol Disord 2003','moderate','2026-08-24','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('propolis','프로폴리스추출물','Propolis Extract',array['soothing','hydration']::text[],'mint','꿀벌이 나무 수지를 모아 만든 물질의 추출물이에요. 진정과 촉촉한 광택 연출 목적으로 배합돼요.','프로폴리스추출물에는 카페익애씨드페네틸에스터(CAPE), 크리신, 갈란진 같은 플라보노이드와 페놀산이 풍부해요. 실험실 연구에서 항산화, 염증 신호 완화, 트러블 관련 균의 성장 억제가 보고돼 있고, 상처 부위 회복을 도왔다는 동물 연구도 있어요. 원산지와 식물 종류에 따라 조성이 크게 달라 브라질산 그린 프로폴리스 등이 구분돼 쓰이기도 해요. 벌 유래 성분이나 포플러 알레르기가 있다면 접촉 반응이 보고돼 있으니 팔 안쪽 테스트 후 쓰는 편이 권장돼요. 나이아신아마이드, 히알루론산, 꿀추출물과 함께 쓰기 무난해요.',array['niacinamide','hyaluronic-acid','honey','centella']::text[],'{}'::text[],array['breakout','dryness']::text[],'Kurek-Górecka A et al., Molecules 2020; Walgrave SE et al., Dermatitis 2005','limited','2026-08-24','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('calendula','카렌듈라꽃추출물','Calendula Officinalis Flower Extract',array['soothing']::text[],'mint','금잔화라고도 하는 카렌듈라 꽃 추출물이에요. 순한 진정 목적의 아기·민감 피부 제품에 자주 쓰여요.','카렌듈라꽃추출물에는 트리테르펜 에스터(파라독시올 등), 플라보노이드, 카로티노이드, 소량의 정유가 들어 있어요. 트리테르펜 성분의 염증 신호 완화와 상처 부위 회복 보조가 실험실·동물 연구에서 보고돼 있고, 유럽에서는 전통적으로 피부 손질에 쓰여 온 약용 식물로 분류돼요. 사람 대상 근거는 방사선 피부염 예방 연구 등 일부가 있으나 화장품 농도에서는 제한적이에요. 국화과 식물이라 관련 알레르기가 있다면 주의가 필요하고, 자극 보고는 드문 편이에요. 판테놀, 캐모마일꽃추출물, 알란토인과 함께 진정 라인에 자주 배합돼요.',array['panthenol','chamomile','allantoin','centella']::text[],'{}'::text[],array['breakout','barrier']::text[],'Givol O et al., Wound Repair Regen 2019; EMA HMPC Assessment Report on Calendula officinalis (2018)','limited','2026-08-24','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('chamomile','캐모마일꽃추출물','Chamomilla Recutita (Matricaria) Flower Extract',array['soothing']::text[],'mint','비사보롤과 카마줄렌 등을 함유한 꽃 추출물로, 진정 목적의 토너·크림에 자주 쓰여요.','독일 캐모마일(마트리카리아) 꽃에서 얻는 추출물로, 알파-비사보롤·카마줄렌·아피제닌 같은 성분이 들어 있어 진정·항산화 목적으로 배합돼요. 토너나 수딩 크림처럼 세안 직후 단계에 흔히 들어가며 아침·저녁 구분 없이 사용되는 편이에요. 다만 국화과 식물이라 국화과 알레르기가 있는 경우 접촉 반응이 보고된 적이 있어, 처음에는 소량으로 반응을 살펴보는 것이 권장돼요. 추출 방식에 따라 향과 성분 조성이 달라질 수 있어요.',array['bisabolol','allantoin','panthenol','centella']::text[],'{}'::text[],array['breakout','barrier']::text[],'CIR Expert Panel Final Report (Chamomilla Recutita); 대한화장품협회 성분사전','moderate','2026-07-14','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('licochalcone','리코찰콘A','Licochalcone A',array['soothing','antioxidant']::text[],'mint','감초에서 분리한 성분으로, 붉은 기와 피지가 함께 고민인 피부용 진정 제품에 자주 쓰여요.','중국 감초(Glycyrrhiza inflata) 뿌리에서 분리한 찰콘 계열 화합물이에요. 활성산소를 줄이고 염증 신호 경로를 조절하는 작용이 실험실·소규모 임상 연구에서 보고되어, 붉은 기와 피지가 함께 고민인 피부용 라인에 배합되는 편이에요. 감초뿌리추출물보다 정제도가 높은 단일 성분이라 비교적 낮은 농도(0.01~0.1% 수준)로 쓰이는 경우가 많고, 아침·저녁 모두 사용돼요. 반응은 개인차가 있을 수 있어요.',array['azelaic-acid','niacinamide','zinc-pca','licorice']::text[],'{}'::text[],array['breakout','sebum']::text[],'Kolbe L et al., Arch Dermatol Res 2006; CIR Expert Panel','moderate','2026-07-16','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('mung-bean','녹두추출물','Phaseolus Radiatus Seed Extract',array['soothing','sebum']::text[],'mint','녹두 씨앗에서 얻은 추출물로, 예로부터 세안과 피지 관리 목적으로 쓰여 온 성분이에요.','녹두 씨앗 추출물에는 비텍신·이소비텍신 같은 플라보노이드와 사포닌이 들어 있어 항산화·진정 목적으로 배합돼요. 전통적으로 녹두 가루를 세안에 활용한 배경이 있어 한국 브랜드의 클렌저·클레이 마스크·피지 진정 라인에 자주 등장해요. 추출물 자체는 자극이 낮은 편으로 알려져 있지만, 콩과 식물이라 관련 알레르기가 있다면 반응을 살펴보는 것이 권장돼요. 사람 대상 임상 근거는 아직 제한적인 편이에요.',array['houttuynia','green-tea','zinc-pca','kaolin']::text[],'{}'::text[],array['breakout','sebum']::text[],'CIR Expert Panel; 대한화장품협회 성분사전','limited','2026-07-18','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('portulaca','쇠비름추출물','Portulaca Oleracea Extract',array['soothing']::text[],'mint','쇠비름에서 얻은 추출물로, 예민하게 반응하는 피부를 위한 진정 제품에 자주 쓰여요.','쇠비름 전초에서 얻는 추출물로, 오메가-3 지방산과 플라보노이드·비타민류를 함유하는 것으로 알려져 있어요. 히스타민 반응과 염증 매개 물질을 줄이는 작용이 실험실 연구에서 보고되어 자극받은 피부를 위한 수딩 젤·크림에 배합되는 편이에요. 보통 다른 진정 성분과 함께 소량으로 배합되며 아침·저녁 구분 없이 쓰여요. 사람을 대상으로 한 임상 자료는 제한적이라 기대치는 보조적인 수준으로 두는 편이 알맞아요.',array['centella','allantoin','panthenol','beta-glucan']::text[],'{}'::text[],array['breakout']::text[],'CIR Expert Panel; 대한화장품협회 성분사전','limited','2026-07-20','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('peony','작약뿌리추출물','Paeonia Lactiflora Root Extract',array['soothing','tone']::text[],'mint','작약 뿌리 추출물로, 붉은 기 진정과 맑은 톤을 목표로 하는 한방 계열 제품에 자주 쓰여요.','작약 뿌리에는 페오니플로린이라는 배당체 성분이 들어 있어 항산화·진정 목적으로 배합돼요. 실험실 연구에서 멜라닌 생성 관련 효소 활성을 낮추는 작용도 보고되어 톤 케어 라인에도 쓰이지만, 사람 대상 임상 자료는 아직 제한적인 편이에요. 한방 화장품이나 에센스·크림에 다른 식물 추출물과 함께 소량 배합되는 경우가 많고, 아침·저녁 구분 없이 사용돼요. 반응은 개인차가 있을 수 있어요.',array['licorice','niacinamide','ginseng','centella']::text[],'{}'::text[],array['dullness','breakout']::text[],'CIR Expert Panel; 대한화장품협회 성분사전','limited','2026-07-22','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('ginseng','인삼뿌리추출물','Panax Ginseng Root Extract',array['firming','antioxidant']::text[],'plum','인삼 뿌리 추출물로, 탄력과 생기 있는 톤을 위한 한방 계열 크림·앰플에 자주 쓰여요.','진세노사이드라 불리는 사포닌 성분이 주요 활성 물질로, 항산화 작용과 콜라겐 합성 관련 신호를 돕는 결과가 실험실 및 일부 소규모 임상 연구에서 보고되었어요. 크림·앰플·아이크림 등 탄력 라인에 자주 배합되며, 추출 부위(뿌리·열매·발효)와 방식에 따라 조성이 달라져요. 아침·저녁 모두 사용되고 다른 활성 성분과 조합하기 무난한 편이에요. 특유의 향이 있어 향에 민감한 경우 참고하는 것이 좋아요.',array['adenosine','peptides','niacinamide','hyaluronic-acid']::text[],'{}'::text[],array['firming','dullness']::text[],'CIR Expert Panel Final Report (Panax Ginseng); 대한화장품협회 성분사전','moderate','2026-07-24','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('zinc-pca','징크PCA','Zinc PCA',array['sebum']::text[],'butter','아연과 보습 성분 PCA가 결합한 형태로, 피지가 신경 쓰이는 피부용 토너·세럼에 자주 쓰여요.','피부 천연 보습인자(NMF)의 하나인 PCA에 아연이 결합한 염이에요. 아연 이온은 피지 분비 관련 5α-환원효소 활성을 낮추고 여드름 관련 균의 증식을 억제하는 작용이 실험실 연구에서 보고되어, 토너·세럼·젤 타입 피지 케어 제품에 0.1~1% 수준으로 배합되는 편이에요. 수렴감이 있어 건조한 피부에서는 당김이 느껴질 수 있으니 보습 단계와 함께 쓰는 것이 권장돼요. 아침·저녁 모두 사용돼요.',array['niacinamide','salicylic-acid','centella','houttuynia']::text[],'{}'::text[],array['sebum','breakout']::text[],'CIR Expert Panel (Zinc Salts); 대한화장품협회 성분사전','moderate','2026-07-26','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('tea-tree','티트리잎오일','Melaleuca Alternifolia (Tea Tree) Leaf Oil',array['sebum','soothing']::text[],'butter','티트리 잎에서 증류한 에센셜오일로, 트러블 부위 스팟 케어 제품에 자주 쓰여요.','테르피넨-4-올이 주요 성분인 에센셜오일로, 항균 작용이 여러 실험실 연구에서 보고되었고 5% 젤을 사용한 소규모 임상 연구도 있어요. 다만 원액은 자극이 강해 화장품에서는 대개 희석해 배합되며, 특히 산화된 오일은 접촉 감작(알레르기 반응)의 원인으로 알려져 있어요. 향 성분이기도 하므로 다른 에센셜오일 제품과 함께 쓰면 누적 노출이 늘어날 수 있어요. 처음에는 국소 부위에 소량으로 시작하고, 개봉 후 오래된 제품은 피하는 편이 권장돼요.',array['zinc-pca','niacinamide','centella']::text[],array['retinol','benzoyl-peroxide','lavender-oil']::text[],array['breakout','sebum']::text[],'Enshaieh S et al., Indian J Dermatol Venereol Leprol 2007; EU SCCS Opinion on Tea Tree Oil','moderate','2026-07-28',array['active','essential-oil','fragrance']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('sulfur','유황','Sulfur',array['sebum','exfoliation']::text[],'butter','오래전부터 쓰여 온 광물 성분으로, 피지와 트러블 부위용 마스크·스팟 제품에 쓰여요.','각질을 부드럽게 만드는 각질용해 작용과 항균 작용이 알려진 성분으로, 미국 FDA OTC 여드름 모노그래프에서 3~10% 범위로 인정되고 있어요. 클레이와 함께 스팟 마스크나 세안제에 배합되는 경우가 많고, 특유의 냄새가 있어 보통 씻어내는 제형이나 국소 부위용으로 쓰여요. 건조함과 벗겨짐을 유발할 수 있어 얼굴 전체보다는 필요한 부위에, 저녁 위주로 사용하는 편이 권장돼요. 다른 각질 관리 성분과 같은 날 겹치면 자극이 누적될 수 있어요.',array['kaolin','niacinamide','panthenol']::text[],array['retinol','benzoyl-peroxide','salicylic-acid','glycolic-acid']::text[],array['breakout','sebum']::text[],'FDA OTC Acne Monograph (21 CFR 333); Gupta AK & Nicol K, J Drugs Dermatol 2004','moderate','2026-07-30',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('benzoyl-peroxide','벤조일퍼옥사이드','Benzoyl Peroxide',array['sebum']::text[],'butter','활성산소를 내놓아 여드름 관련 균을 억제하는 성분으로, 트러블 스팟 제품에 널리 쓰여요.','피부에서 분해되며 활성산소를 내놓아 C. acnes 균을 억제하는 작용이 잘 정리되어 있고, 항생제와 달리 내성 문제가 적은 것으로 알려져 있어요. 해외에서는 2.5~10% 범위의 OTC 성분이며, 2.5%도 고농도와 비슷한 결과를 보였다는 연구가 있어 낮은 농도부터 시작하는 것이 권장돼요. 강한 산화제라 레티놀·순수 비타민C와 같은 단계에 겹치면 상대 성분이 산화될 수 있고, 건조·벗겨짐·붉은 기가 흔한 편이에요. 섬유를 탈색시킬 수 있어 수건·베개 커버에 닿지 않도록 주의하고, 국내에서는 의약품으로 분류돼요.',array['niacinamide','panthenol','ceramide','hyaluronic-acid']::text[],array['retinol','retinal','ascorbic-acid','glycolic-acid']::text[],array['breakout']::text[],'FDA OTC Acne Monograph (21 CFR 333); Mills OH et al., Int J Dermatol 1986','high','2026-08-01',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('kaolin','카올린(클레이)','Kaolin',array['sebum']::text[],'butter','고운 백색 점토 성분으로, 유분과 노폐물을 흡착하는 클레이 마스크에 자주 쓰여요.','알루미늄 규산염으로 이루어진 천연 점토로, 입자 표면에 유분과 노폐물을 흡착하는 물리적 작용을 해요. 벤토나이트보다 흡착력이 온화한 편이라 건성·복합성 피부용 클레이 마스크나 세안제, 파우더에도 두루 쓰여요. 씻어내는 제형이 대부분이고, 얼굴 전체보다 T존처럼 유분이 많은 부위에 주 1~2회 정도 쓰는 방식이 흔해요. 마스크를 완전히 말려 갈라질 때까지 두면 오히려 당김이 심해질 수 있어 촉촉할 때 씻어내는 것이 권장돼요.',array['sulfur','mung-bean','zinc-pca','glycerin']::text[],'{}'::text[],array['sebum']::text[],'CIR Expert Panel Final Report (Kaolin); 대한화장품협회 성분사전','moderate','2026-08-02','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('piroctone-olamine','피록톤올아민','Piroctone Olamine',array['sebum']::text[],'butter','두피 비듬 샴푸로 잘 알려진 항진균 성분으로, 얼굴 피지 라인에도 쓰이기 시작했어요.','말라세지아 같은 효모균의 증식을 억제하는 항진균 성분으로, 원래 비듬 샴푸에 0.5~1% 수준으로 쓰여 왔어요. 최근에는 피지가 많은 부위의 균 균형을 다루는 개념으로 세안제·토너·크림에도 낮은 농도로 배합되는 편이에요. 지루성 피부 고민이나 곰팡이성 트러블(모낭염)과 관련해 언급되지만, 얼굴 화장품에서의 임상 자료는 두피보다 제한적이에요. 배합 한도가 정해진 성분이라 허용 농도 안에서 사용되며, 두피와 얼굴 제품을 동시에 쓰면 노출이 겹칠 수 있어요.',array['zinc-pca','salicylic-acid','niacinamide']::text[],'{}'::text[],array['breakout','sebum']::text[],'EU SCCS Opinion (Piroctone Olamine, SCCS/1613/19); CIR Expert Panel','moderate','2026-08-03','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('silica','실리카','Silica',array['sebum']::text[],'butter','미세한 구형 입자가 유분을 머금어 번들거림을 줄여 주는 성분으로, 파우더와 프라이머에 쓰여요.','이산화규소로 이루어진 분체 성분으로, 다공성 구형 입자가 피지를 흡수하고 빛을 산란시켜 매트하고 보송한 느낌을 만들어요. 스킨케어에서는 피지 조절 크림이나 프라이머·선크림에 배합되어 유분감을 줄이고, 색조에서는 파우더의 사용감을 부드럽게 하는 역할을 해요. 화장품용 비결정성 실리카는 피부에 흡수되지 않고 표면에 머무르는 것으로 알려져 있으며, 흡착력이 강해 건성 피부에서는 당김이 느껴질 수 있어요. 세정으로 씻어내면 잔여감은 거의 남지 않아요.',array['kaolin','zinc-pca','niacinamide','dimethicone']::text[],'{}'::text[],array['sebum']::text[],'CIR Expert Panel Final Report (Silica); EU SCCS Opinion','moderate','2026-08-04','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('glycolic-acid','글라이콜릭애씨드(AHA)','Glycolic Acid',array['exfoliation','renewal']::text[],'lilac','분자가 가장 작은 AHA로, 각질을 정돈해 결과 톤을 관리하는 제품에 널리 쓰이는 대표 산 성분이에요.','사탕수수 유래 알파하이드록시산(AHA) 중 분자가 가장 작아 각질층 침투가 빠르고, 각질세포 사이의 결합을 느슨하게 해 묵은 각질이 떨어지도록 돕는 작용이 잘 알려져 있어요. 홈케어 제품에서는 pH 3.5~4 부근, 농도 5~10% 범위가 흔하고 국내에서는 산성도와 농도 규제가 있어요. 처음에는 낮은 농도를 주 1~2회 저녁에 사용하고, 따가움·붉은 기가 지속되면 빈도를 줄이는 것이 권장돼요. 각질층이 얇아지는 만큼 아침 자외선 차단은 필수이고, 레티놀·BHA와 같은 날 겹치면 자극이 누적될 수 있어요.',array['hyaluronic-acid','niacinamide','ceramide','panthenol']::text[],array['retinol','retinal','salicylic-acid','ascorbic-acid']::text[],array['texture','dullness']::text[],'Van Scott EJ & Yu RJ, J Am Acad Dermatol 1984; CIR Expert Panel (Glycolic/Lactic Acid)','high','2026-08-05',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('lactic-acid','락틱애씨드(AHA)','Lactic Acid',array['exfoliation','hydration']::text[],'lilac','AHA 중 비교적 순한 편으로 알려져 있고, 보습감도 어느 정도 남는 각질 관리 성분이에요.','글라이콜릭보다 분자가 커서 침투 속도가 완만하고 자극 부담이 상대적으로 낮은 편이라고 자주 언급돼요. 피부 천연 보습인자(NMF)의 구성 성분이기도 해서 각질 정돈과 함께 수분 유지에 도움을 주는 것으로 알려져 있고, 세라마이드 합성을 자극한다는 연구도 있어요. 홈케어에서는 5~10%, pH 3.5~4 부근 처방이 흔하고, 건조하면서 결이 고민인 경우에 시도되는 편이에요. 저녁 위주로 주 2~3회부터 시작하고 아침에는 자외선 차단제를 챙기는 것이 권장돼요.',array['hyaluronic-acid','niacinamide','ceramide','glycerin']::text[],array['retinol','salicylic-acid','glycolic-acid']::text[],array['texture','dryness']::text[],'Smith WP, J Am Acad Dermatol 1996; CIR Expert Panel (Glycolic/Lactic Acid)','high','2026-08-06',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('mandelic-acid','만델릭애씨드(AHA)','Mandelic Acid',array['exfoliation']::text[],'lilac','분자가 큰 편이라 순한 AHA로 언급되는 성분으로, 예민한 피부의 각질 관리에 자주 소개돼요.','아몬드 유래 AHA로 분자가 커서 각질층에 천천히 스며들어 자극 부담이 낮은 편이라고 알려져 있어요. 약한 항균 특성이 있어 트러블성 각질 관리 제품에도 배합되며, 지용성 성질이 일부 있어 모공 주변 각질에도 접근하기 쉬운 편이에요. 홈케어에서는 5~10%, pH 3.5~4 부근 처방이 흔하고, 다른 AHA보다 색소 침착 우려가 있는 피부에서 먼저 시도되는 경우가 많아요. 그래도 각질 관리 성분이라 저녁 사용과 아침 자외선 차단이 권장돼요.',array['niacinamide','panthenol','hyaluronic-acid','azelaic-acid']::text[],array['retinol','glycolic-acid','salicylic-acid']::text[],array['texture','breakout']::text[],'Garg VK et al., Dermatol Surg 2009; CIR Expert Panel','moderate','2026-08-07',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('salicylic-acid','살리실릭애씨드(BHA)','Salicylic Acid',array['exfoliation','sebum']::text[],'lilac','기름에 잘 녹는 BHA로, 모공 속 피지와 각질을 정돈하는 트러블 케어 제품에 널리 쓰여요.','지용성 베타하이드록시산(BHA)으로 피지와 섞여 모공 안쪽까지 들어가 각질세포의 결합을 느슨하게 하는 작용이 알려져 있어요. 국내 일반 화장품에서는 0.5% 이하로 배합이 허용되고(씻어내는 제품·의약외품은 별도), 해외 OTC 여드름 제품은 0.5~2% 범위예요. pH 3~4 부근에서 잘 작용하며, 아스피린 계열이라 살리실산 알레르기가 있으면 피하는 것이 권장돼요. 건조·따가움이 나타나면 빈도를 줄이고, 레티놀·AHA와 같은 날 겹치면 자극이 누적될 수 있으니 저녁에 하나씩 번갈아 쓰는 방식이 흔해요.',array['niacinamide','zinc-pca','hyaluronic-acid','panthenol']::text[],array['retinol','retinal','glycolic-acid','benzoyl-peroxide']::text[],array['breakout','sebum','texture']::text[],'FDA OTC Acne Monograph (21 CFR 333); Arif T, Clin Cosmet Investig Dermatol 2015','high','2026-08-08',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('lha','카프릴로일살리실릭애씨드(LHA)','Capryloyl Salicylic Acid',array['exfoliation','sebum']::text[],'lilac','살리실산에 지방산 사슬을 붙여 더 순하게 만든 BHA 유도체로, 예민한 피부용 각질 제품에 쓰여요.','살리실산에 8개 탄소의 지방산 사슬을 결합한 유도체(LHA)로, 지용성이 더 높아 각질층 표면과 모공 입구에 머무르며 세포 하나하나 단위로 천천히 떨어져 나가게 돕는 것으로 설명돼요. 피부 pH(약 5.5)에 가까운 조건에서도 작용해 낮은 pH가 필요한 살리실산보다 자극이 적은 편이라고 알려져 있으며, 0.3~1% 정도로 배합되는 경우가 많아요. 그래도 각질 관리 성분이므로 다른 산·레티노이드와 같은 날 겹치면 자극이 누적될 수 있고, 아침 사용 시 자외선 차단이 권장돼요.',array['niacinamide','hyaluronic-acid','panthenol']::text[],array['retinol','salicylic-acid','glycolic-acid']::text[],array['texture','breakout']::text[],'Zeichner JA, J Clin Aesthet Dermatol 2016; CIR Expert Panel','moderate','2026-08-09',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('gluconolactone','글루코노락톤(PHA)','Gluconolactone',array['exfoliation','hydration']::text[],'lilac','분자가 커서 순한 편으로 알려진 PHA 성분으로, 각질 관리에 처음 입문할 때 자주 소개돼요.','폴리하이드록시산(PHA)의 대표 성분으로, 여러 개의 하이드록시기를 가진 큰 분자라 각질층에 천천히 침투해 AHA보다 따가움이 덜한 편이라고 보고돼요. 각질을 정돈하면서 수분을 붙잡는 습윤 성질과 항산화 작용도 함께 알려져 있어, 예민하거나 건조한 피부의 각질 관리 입문 성분으로 자주 소개돼요. 토너·패드·세럼에 3~10% 수준으로 쓰이고 아침·저녁 모두 사용되지만, 각질 관리 성분인 만큼 자외선 차단을 함께 챙기는 것이 권장돼요. 레티놀·다른 산과 겹치면 자극이 누적될 수 있어요.',array['hyaluronic-acid','niacinamide','lactobionic-acid','panthenol']::text[],array['retinol','glycolic-acid','salicylic-acid']::text[],array['texture','dullness']::text[],'Grimes PE et al., Cutis 2004; CIR Expert Panel','moderate','2026-08-10',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('lactobionic-acid','락토바이오닉애씨드(PHA)','Lactobionic Acid',array['exfoliation','hydration']::text[],'lilac','우유 유래 당에서 만든 PHA로, 순한 각질 정돈과 보습을 함께 노리는 제품에 쓰여요.','락토스에서 유래한 폴리하이드록시산(PHA)으로, 글루코노락톤보다 분자가 더 크고 하이드록시기가 많아 피부 표면에서 천천히 작용해요. 수분을 강하게 붙잡는 습윤 특성과 금속 이온을 붙잡는 킬레이트 작용, 항산화 작용이 함께 보고되어 각질 정돈과 보습을 동시에 노리는 처방에 쓰여요. 보통 3~8% 수준으로 토너·크림에 배합되며, AHA에 비해 따가움이 적어 예민한 피부에서 시도되는 편이에요. 각질 관리 성분이므로 아침 자외선 차단을 함께 챙기는 것이 권장돼요.',array['gluconolactone','hyaluronic-acid','ceramide','niacinamide']::text[],array['retinol','glycolic-acid']::text[],array['texture']::text[],'Grimes PE et al., Cutis 2004; Green BA, Yu RJ & Van Scott EJ, Clin Dermatol 2009','moderate','2026-08-11',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('papain','파파인(효소)','Papain',array['exfoliation']::text[],'lilac','파파야에서 얻은 단백질 분해 효소로, 산 없이 각질을 정돈하는 효소 세안제에 자주 쓰여요.','파파야 열매에서 얻는 단백질 분해 효소(프로테아제)로, 각질세포를 이어 주는 단백질을 분해해 묵은 각질이 떨어지도록 돕는 방식으로 작용해요. 산과 달리 낮은 pH가 필요하지 않고 물과 만나 활성화되므로 파우더 세안제나 워시오프 마스크에 배합되는 경우가 많아요. 열과 습기에 약해 제형 안정성이 중요하고, 단백질 성분이라 드물게 접촉 알레르기가 보고된 적이 있어 처음에는 소량으로 살펴보는 것이 권장돼요. 주 1~3회 정도의 사용이 흔해요.',array['glycerin','panthenol','aloe']::text[],array['retinol','glycolic-acid','cellulose']::text[],array['texture']::text[],'CIR Expert Panel (Papain); 대한화장품협회 성분사전','limited','2026-08-12','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('cellulose','셀룰로오스(피지컬 각질)','Cellulose',array['exfoliation']::text[],'lilac','식물 섬유로 만든 부드러운 알갱이로, 문질러서 각질을 정돈하는 스크럽 제품에 쓰여요.','식물 세포벽 성분인 셀룰로오스를 작은 입자로 가공해 물리적으로 각질을 밀어내는 스크럽 원료로, 플라스틱 마이크로비즈를 대체하는 생분해성 소재로 자리 잡았어요. 입자 크기와 형태(구형·부정형)에 따라 마찰감이 달라지며, 각질을 화학적으로 녹이는 것이 아니라 문지르는 힘으로 떨어내는 방식이라 손의 힘 조절이 중요해요. 세게 문지르면 미세한 상처와 붉은 기가 생길 수 있어 주 1~2회, 부드럽게 굴리듯 사용하는 것이 권장돼요. 산·레티놀과 같은 날 겹치면 자극이 누적될 수 있어요.',array['glycerin','panthenol','kaolin']::text[],array['retinol','glycolic-acid','salicylic-acid','papain']::text[],array['texture']::text[],'CIR Expert Panel Final Report (Cellulose); 대한화장품협회 성분사전','limited','2026-08-13','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('tocopherol','토코페롤(비타민E)','Tocopherol',array['antioxidant','barrier']::text[],'gold','지용성 비타민E로, 항산화와 제품 산화 방지 목적으로 매우 널리 배합되는 성분이에요.','세포막과 피지 같은 지질 부분에서 활성산소 연쇄 반응을 끊는 지용성 항산화 성분으로, 피부에 자연적으로 존재하는 항산화 체계의 일부이기도 해요. 오일·크림에 0.1~1% 수준으로 배합되며, 순수 비타민C·페룰릭애씨드와 함께 쓰면 서로의 안정성과 항산화 지속력이 높아진다는 연구가 잘 알려져 있어요. 유분이 있어 지성 피부에서는 오일리한 제형이 부담될 수 있고, 드물게 접촉 반응이 보고되기도 해요. 아침 자외선 차단제 아래 항산화층으로 쓰는 방식이 흔해요.',array['ascorbic-acid','ferulic-acid','squalane','ceramide']::text[],'{}'::text[],array['dullness','barrier']::text[],'Lin FH et al., J Invest Dermatol 2005; CIR Expert Panel (Tocopherol)','high','2026-08-14','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('ferulic-acid','페룰릭애씨드','Ferulic Acid',array['antioxidant']::text[],'gold','식물 세포벽에서 얻는 항산화 성분으로, 비타민C·E와 함께 배합될 때의 시너지가 자주 언급돼요.','쌀겨·귀리 같은 곡물 세포벽에 들어 있는 페놀산 계열 항산화 성분이에요. 단독으로도 활성산소를 중화하지만, 15% 순수 비타민C와 1% 비타민E에 0.5% 페룰릭애씨드를 더하면 광보호 작용이 두 배 가까이 늘고 비타민C의 안정성도 높아졌다는 연구가 널리 인용돼요. 이 때문에 아침 항산화 세럼 처방에 자주 들어가며, 낮은 pH 제형에서 안정적이에요. 특유의 향이 있을 수 있고, 반응은 개인차가 있을 수 있어요.',array['ascorbic-acid','tocopherol','resveratrol']::text[],'{}'::text[],array['dullness']::text[],'Lin FH et al., J Invest Dermatol 2005; Zduńska K et al., Skin Pharmacol Physiol 2018','moderate','2026-08-15','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('resveratrol','레스베라트롤','Resveratrol',array['antioxidant']::text[],'gold','포도 껍질과 레드와인으로 알려진 폴리페놀 항산화 성분으로, 안티에이징 세럼에 자주 쓰여요.','포도·땅콩·호장근 등에서 얻는 스틸벤 계열 폴리페놀로, 활성산소를 직접 중화하고 세포 내 항산화 효소 발현을 돕는 작용이 실험실 연구에서 보고되어 있어요. 화장품에서는 0.1~1% 수준으로 배합되고, 빛과 산소에 약한 편이라 불투명 용기와 다른 항산화 성분(비타민E·페룰릭) 조합이 흔해요. 저녁에 바르면 낮 동안 쌓인 산화 스트레스를 다루는 개념으로 소개되지만, 사람 대상 임상 자료는 아직 소규모예요. 붉은 기가 잘 생기는 피부는 소량으로 시작하는 것이 권장돼요.',array['tocopherol','ferulic-acid','niacinamide','hyaluronic-acid']::text[],'{}'::text[],array['dullness','firming']::text[],'Farris P et al., J Drugs Dermatol 2013; CIR Expert Panel','moderate','2026-08-16','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('ubiquinone','유비퀴논(코엔자임Q10)','Ubiquinone',array['antioxidant','firming']::text[],'gold','코엔자임Q10으로 알려진 성분으로, 세포 에너지 대사와 항산화 관련 탄력 제품에 쓰여요.','미토콘드리아에서 에너지 생성에 관여하는 지용성 항산화 물질로, 피부 내 함량이 나이가 들수록 줄어드는 것으로 알려져 있어요. 화장품에서는 노란빛을 띠는 낮은 농도(0.01~0.5% 수준)로 크림·세럼에 배합되며, 활성산소를 줄이고 자외선으로 인한 콜라겐 분해 효소 발현을 낮추는 결과가 실험실과 소규모 임상에서 보고되었어요. 지용성이라 유분 있는 제형에 잘 맞고, 빛에 약해 불투명 용기가 권장돼요. 아침·저녁 모두 사용되며 반응은 개인차가 있을 수 있어요.',array['tocopherol','adenosine','squalane','peptides']::text[],'{}'::text[],array['firming']::text[],'Hoppe U et al., BioFactors 1999; CIR Expert Panel','moderate','2026-08-17','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('astaxanthin','아스타잔틴','Astaxanthin',array['antioxidant']::text[],'gold','새우·연어의 붉은빛을 내는 카로티노이드로, 강한 항산화력으로 알려진 성분이에요.','헤마토코쿠스 조류에서 주로 얻는 붉은색 카로티노이드로, 실험실 연구에서 비타민E보다 훨씬 강한 지질 항산화 능력을 보여 주목받았어요. 자외선으로 인한 산화 스트레스와 콜라겐 분해 효소 활성을 낮추는 결과가 세포 및 소규모 임상 연구에서 보고되었고, 화장품에서는 0.01~0.1% 정도의 낮은 농도로도 제형이 주황빛을 띨 만큼 색이 진해요. 빛과 열에 약해 불투명 용기와 서늘한 보관이 권장되고, 지용성이라 오일·크림 제형에 잘 맞아요. 아침·저녁 구분 없이 쓰여요.',array['tocopherol','hyaluronic-acid','squalane','niacinamide']::text[],'{}'::text[],array['dullness','firming']::text[],'Tominaga K et al., Acta Biochim Pol 2012; Davinelli S et al., Nutrients 2018','moderate','2026-08-18','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('black-tea','홍차발효추출물','Black Tea Ferment',array['antioxidant','firming']::text[],'gold','홍차를 발효해 얻은 성분으로, 항산화와 탄력 관련 에센스·크림에 자주 쓰여요.','홍차 잎을 효모·유산균 공생체(콤부차 방식)로 발효해 얻은 성분으로, 테아플라빈 같은 홍차 폴리페놀에 발효 과정에서 생긴 유기산·아미노산이 더해진 조성이에요. 활성산소를 줄이고 피부 표면의 매끄러움을 돕는 결과가 원료사 자료와 일부 소규모 연구에서 보고되었지만, 독립적인 임상 자료는 아직 제한적인 편이에요. 에센스·크림에 다른 항산화 성분과 함께 배합되며 아침·저녁 모두 사용돼요. 발효물 특유의 향이 있을 수 있고 반응은 개인차가 있을 수 있어요.',array['niacinamide','hyaluronic-acid','green-tea','adenosine']::text[],'{}'::text[],array['firming','dullness']::text[],'CIR Expert Panel; 대한화장품협회 성분사전','limited','2026-08-19','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('galactomyces','갈락토미세스발효여과물','Galactomyces Ferment Filtrate',array['antioxidant','tone','hydration']::text[],'gold','발효 여과물 계열 성분으로, 톤과 보습 목적의 퍼스트 에센스에 자주 사용돼요.','갈락토미세스 효모를 배양한 뒤 여과해 얻는 성분으로, 아미노산·유기산·미네랄·비타민류를 포함하는 것으로 알려져 있어요. 피부의 항산화 방어 체계(Nrf2 경로)를 활성화하고 각질층 수분과 결을 돕는 결과가 실험실 및 소규모 연구에서 보고되었어요. 퍼스트 에센스처럼 세안 직후 고함량(90% 이상)으로 쓰는 제품이 많고, 아침·저녁 모두 사용돼요. 발효 특유의 향이 있을 수 있고, 효모 유래 성분이라 말라세지아 관련 트러블이 잦은 피부는 반응을 살펴보는 편이 권장돼요.',array['niacinamide','hyaluronic-acid','glycerin','ascorbyl-glucoside']::text[],'{}'::text[],array['dullness','texture']::text[],'Takei K et al., J Dermatol Sci 2015; 대한화장품협회 성분사전','moderate','2026-08-20','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('bifida','비피다발효용해물','Bifida Ferment Lysate',array['antioxidant','barrier']::text[],'gold','유산균 발효 용해물로, 장벽과 스트레스 받은 피부 관련 제품에 자주 등장하는 성분이에요.','비피도박테리움 균을 배양한 뒤 파쇄·용해해 얻은 성분으로, 균의 세포벽 조각·대사산물·펩타이드가 섞인 조성이에요. 자외선으로 손상된 DNA 복구를 돕고 각질층 수분 손실(TEWL)을 줄이는 결과가 소규모 임상에서 보고되어 장벽·안티에이징 에센스에 자주 배합돼요. 살아 있는 균이 아니라 용해물이므로 제형 내 안정성 문제가 적고, 아침·저녁 모두 사용돼요. 발효물 특유의 향이 있을 수 있고 반응은 개인차가 있을 수 있어요.',array['ceramide','panthenol','hyaluronic-acid','niacinamide']::text[],'{}'::text[],array['barrier','dullness']::text[],'Gueniche A et al., Exp Dermatol 2010; CIR Expert Panel','moderate','2026-08-21','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('yeast-extract','효모발효추출물','Saccharomyces Ferment Filtrate',array['antioxidant','hydration']::text[],'gold','효모를 발효·여과해 얻은 성분으로, 촉촉하고 맑은 느낌을 위한 에센스에 자주 쓰여요.','사카로미세스 효모를 배양한 뒤 여과한 성분으로, 아미노산·펩타이드·베타글루칸·비타민B군 등을 포함하는 것으로 알려져 있어요. 항산화 작용과 각질층 수분 보유를 돕는 결과가 실험실 및 원료사 자료에서 보고되었고, 발효 에센스와 토너에 넓은 농도 범위로 배합돼요. 자극이 낮은 편으로 알려져 아침·저녁 모두 사용되지만, 효모 유래 성분이라 관련 알레르기가 있거나 곰팡이성 트러블이 잦은 피부는 반응을 살펴보는 편이 권장돼요. 독립적인 임상 자료는 아직 제한적이에요.',array['hyaluronic-acid','niacinamide','beta-glucan','glycerin']::text[],'{}'::text[],array['dullness','dryness']::text[],'CIR Expert Panel (Saccharomyces Ferment); 대한화장품협회 성분사전','limited','2026-08-22','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('algae','해조추출물','Algae Extract',array['hydration','antioxidant']::text[],'sky','바다 해조류에서 얻은 추출물로, 미네랄과 다당류가 풍부해 보습 제품에 자주 쓰여요.','갈조류·홍조류·녹조류 등 다양한 해조류에서 얻는 추출물로, 알긴산·카라기난·후코이단 같은 다당류와 미네랄·아미노산을 포함해요. 다당류가 피부 표면에 수분막을 만들어 보습감을 주고, 일부 해조 성분은 항산화와 콜라겐 분해 효소 억제 작용이 실험실 연구에서 보고되었어요. "Algae Extract"라는 표기는 종을 특정하지 않아 제품마다 조성이 크게 다를 수 있고, 요오드 함량이 있는 원료도 있어 갑상선 관련 우려가 있다면 참고하는 것이 좋아요. 아침·저녁 모두 사용돼요.',array['hyaluronic-acid','glycerin','niacinamide','collagen']::text[],'{}'::text[],array['dryness','firming']::text[],'CIR Expert Panel (Algae-derived ingredients); Pangestuti R & Kim SK, J Funct Foods 2011','limited','2026-08-23','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('rosemary','로즈마리잎추출물','Rosmarinus Officinalis (Rosemary) Leaf Extract',array['antioxidant','soothing']::text[],'gold','로즈마리 잎 추출물로, 항산화와 제품 산화 방지 목적으로 자주 배합되는 향이 있는 성분이에요.','로즈마리 잎에는 카르노식산·로즈마린산 같은 강한 항산화 폴리페놀이 들어 있어, 피부 항산화 목적뿐 아니라 오일 제형의 산패를 늦추는 천연 산화 방지제로도 널리 쓰여요. 피지 관련 제품에서는 항균·수렴 목적으로 소량 배합되는 편이에요. 다만 추출물 자체에 향 성분(1,8-시네올, 캄퍼 등)이 있어 향에 민감한 피부에서는 반응이 나타날 수 있고, 여러 제품에 겹쳐 있으면 누적 노출이 늘어날 수 있어요. 에센셜오일이 아닌 추출물은 상대적으로 향 성분 농도가 낮은 편이에요.',array['green-tea','tocopherol','jojoba-oil','zinc-pca']::text[],array['citrus-oil','lavender-oil']::text[],array['sebum']::text[],'CIR Expert Panel Final Report (Rosmarinus Officinalis); EU SCCS Opinion on Fragrance Allergens','moderate','2026-08-24',array['fragrance']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('retinol','레티놀','Retinol',array['renewal','firming']::text[],'lilac','비타민A 계열 대표 성분으로, 결·탄력 관련 제품에 널리 쓰이고 저녁 사용이 일반적이에요.','피부 안에서 레티날을 거쳐 레티노익애씨드로 두 단계 전환된 뒤 작용하는 1세대 레티노이드로, 각질 턴오버를 촉진하고 콜라겐 합성 관련 신호를 돕는 결과가 수십 년간의 연구로 정리되어 있어요. 국내 주름 개선 기능성 고시 원료이며, 0.01~0.3% 정도의 낮은 농도부터 주 2회 저녁에 시작해 서서히 빈도를 늘리는 방식이 일반적이에요. 초기에는 A-반응이라 불리는 건조·각질·붉은 기가 나타날 수 있고, 빛과 산소에 불안정해 불투명 용기가 필요해요. 아침 자외선 차단은 필수이고, AHA·BHA·벤조일퍼옥사이드와 같은 날 겹치면 자극이 누적될 수 있어요.',array['ceramide','panthenol','niacinamide','squalane']::text[],array['glycolic-acid','salicylic-acid','benzoyl-peroxide','ascorbic-acid']::text[],array['firming','texture','pigmentation']::text[],'Kligman AM et al., J Am Acad Dermatol 1986; Kafi R et al., Arch Dermatol 2007','high','2026-08-25',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('retinal','레티날','Retinal',array['renewal','firming']::text[],'lilac','레티놀보다 활성형에 한 단계 가까운 비타민A로, 비교적 빠르게 작용하는 것으로 알려진 성분이에요.','레티날데하이드라고도 불리며, 피부 안에서 한 번의 산화 과정만 거치면 활성형인 레티노익애씨드로 바뀌는 1세대 레티노이드예요. 이 때문에 같은 농도의 레티놀보다 전환 효율이 높다고 보고되며, 항균 작용이 있어 트러블 경향 피부에서도 시도되는 편이에요. 홈케어 제품은 0.05~0.1% 수준이 흔하고, 노란빛이 강해 제형이 색을 띠어요. 초기 A-반응(건조·각질·붉은 기)이 나타날 수 있어 주 2회 저녁 소량으로 시작해 늘리는 것이 권장되고, 아침 자외선 차단은 필수예요. 산·벤조일퍼옥사이드와 겹치면 자극이 누적될 수 있어요.',array['ceramide','panthenol','niacinamide','hyaluronic-acid']::text[],array['glycolic-acid','salicylic-acid','benzoyl-peroxide','ascorbic-acid']::text[],array['firming','texture']::text[],'Saurat JH et al., J Invest Dermatol 1994; Creidi P et al., J Am Acad Dermatol 1998','high','2026-08-26',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('retinyl-palmitate','레티닐팔미테이트','Retinyl Palmitate',array['renewal']::text[],'lilac','레티놀에 지방산을 붙여 안정화한 형태로, 가장 순하지만 작용도 완만한 비타민A 유도체예요.','레티놀에 팔미틱애씨드를 결합한 에스터 형태로, 피부 안에서 레티놀→레티날→레티노익애씨드의 세 단계 전환을 거쳐야 해서 같은 농도에서는 레티놀보다 작용이 완만한 것으로 알려져 있어요. 대신 산화에 비교적 안정적이고 자극이 적어 데일리 크림·아이크림·입문용 제품에 자주 쓰이며, 국내 주름 개선 기능성 고시 원료이기도 해요. 초기 A-반응은 드문 편이지만 비타민A 계열이므로 저녁 사용과 아침 자외선 차단이 권장돼요. 자외선 아래에서의 광안정성 논란이 있었던 만큼, 낮에 바른다면 선크림 아래 두는 것이 알맞아요.',array['ceramide','tocopherol','squalane','hyaluronic-acid']::text[],array['glycolic-acid','benzoyl-peroxide']::text[],array['firming']::text[],'CIR Expert Panel Final Report (Retinol and Retinyl Palmitate); 식약처 기능성화장품 고시 원료','moderate','2026-08-27',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('hpr','하이드록시피나콜론레티노에이트','Hydroxypinacolone Retinoate',array['renewal','firming']::text[],'lilac','전환 과정 없이 수용체에 직접 결합하는 것으로 알려진 차세대 레티노이드 에스터예요.','레티노익애씨드의 에스터 형태로, 이론상 피부 안에서 별도 전환 없이 레티노이드 수용체(RAR)에 직접 결합할 수 있어 "그라나액티브 레티노이드"라는 원료명으로 알려져 있어요. 레티놀 대비 자극이 낮으면서 비슷한 유전자 발현 변화를 보였다는 원료사 및 소규모 연구 자료가 있지만, 독립적인 장기 임상 자료는 아직 제한적이에요. 0.1~2% 수준으로 배합되며 초기 A-반응이 덜한 편이라 입문용으로 소개되지만, 비타민A 계열인 만큼 저녁 사용과 아침 자외선 차단이 권장돼요. 산·벤조일퍼옥사이드와 겹치면 자극이 누적될 수 있어요.',array['ceramide','niacinamide','panthenol','hyaluronic-acid']::text[],array['glycolic-acid','salicylic-acid','benzoyl-peroxide']::text[],array['firming','texture']::text[],'Zasada M & Budzisz E, Adv Dermatol Allergol 2019; Grana Active Retinoid 원료사 자료','limited','2026-08-28',array['active']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('bakuchiol','바쿠치올','Bakuchiol',array['firming','antioxidant']::text[],'plum','보골지 씨앗에서 얻은 식물 성분으로, 화장품에서 레티놀 대안으로 자주 소개돼요.','보골지(Psoralea corylifolia) 씨앗에서 얻는 메로테르펜 화합물로, 구조는 레티놀과 다르지만 콜라겐 관련 유전자 발현 패턴이 비슷하다는 연구가 있어 "식물성 레티놀 대안"으로 알려졌어요. 0.5% 바쿠치올과 0.5% 레티놀을 12주 비교한 이중맹검 연구에서 비슷한 결과와 더 적은 자극이 보고되었어요. 빛에 비교적 안정적이라 아침·저녁 모두 사용되고, 임신 중 레티놀을 피하는 경우의 대안으로도 언급되지만 그 자체에 대한 임상 자료가 충분한 건 아니에요. 항산화 작용도 함께 보고되며 반응은 개인차가 있을 수 있어요.',array['niacinamide','ceramide','peptides','hyaluronic-acid']::text[],'{}'::text[],array['firming','texture']::text[],'Dhaliwal S et al., Br J Dermatol 2019; Chaudhuri RK & Bojanowski K, Int J Cosmet Sci 2014','moderate','2026-08-29','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('adenosine','아데노신','Adenosine',array['firming']::text[],'plum','국내 주름 개선 기능성 고시 원료로, 낮은 농도로 크림·에센스에 매우 널리 쓰이는 성분이에요.','몸 안에서 에너지 전달(ATP)의 뼈대가 되는 핵산 성분으로, 피부에서는 섬유아세포의 아데노신 수용체에 결합해 콜라겐·엘라스틴 합성 관련 신호를 돕는 것으로 설명돼요. 식약처 주름 개선 기능성 고시 원료 중 하나로 0.04% 농도로 배합되며, 자극이 낮고 물에 잘 녹아 거의 모든 제형과 pH에서 쓰기 쉬워요. 이런 이유로 한국 화장품 성분표에서 매우 자주 만날 수 있고, 아침·저녁 구분 없이 사용돼요. 단독 임상 자료는 소규모라 다른 탄력 성분과의 조합으로 접근하는 편이 흔해요.',array['peptides','niacinamide','retinol','hyaluronic-acid']::text[],'{}'::text[],array['firming']::text[],'식약처 기능성화장품 고시 원료; Abella ML, Int J Cosmet Sci 2006','moderate','2026-08-30','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('peptides','펩타이드','Palmitoyl Tripeptide-1',array['firming']::text[],'plum','아미노산이 짧게 이어진 사슬 형태의 성분으로, 탄력 관련 세럼·크림에 자주 쓰여요.','팔미토일트라이펩타이드-1은 콜라겐 조각을 모방한 신호 펩타이드에 지방산을 붙여 침투를 도운 형태로, 섬유아세포에 콜라겐 생성 신호를 보내는 개념으로 설계됐어요. 마트릭실(팔미토일펜타펩타이드-4)이나 팔미토일테트라펩타이드-7과 함께 배합되는 경우가 많고, 화장품에서는 ppm 단위의 낮은 농도로 쓰여요. 자극이 낮아 레티놀·산 같은 활성 성분과도 겹쳐 쓰기 무난한 편이지만, 강한 산성 환경에서는 펩타이드가 분해될 수 있다는 지적이 있어요. 아침·저녁 모두 사용되고, 임상 근거는 종류마다 편차가 커요.',array['niacinamide','hyaluronic-acid','adenosine','retinol']::text[],array['ascorbic-acid']::text[],array['firming']::text[],'Lintner K & Peschard O, Int J Cosmet Sci 2000; Gorouhi F & Maibach HI, Int J Cosmet Sci 2009','moderate','2026-08-31','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('copper-peptide','구리펩타이드','Copper Tripeptide-1',array['firming','renewal']::text[],'plum','구리 이온이 결합한 펩타이드(GHK-Cu)로, 재생·탄력 컨셉 앰플에 자주 쓰이는 푸른빛 성분이에요.','글리실-히스티딜-라이신 세 아미노산에 구리 이온이 결합한 복합체로, 상처 회복 과정에서 자연적으로 나오는 신호 물질로 알려져 있어요. 콜라겐·엘라스틴 합성과 손상 조직의 리모델링 관련 유전자 발현을 조절하는 결과가 실험실 및 소규모 임상에서 보고되었고, 제형이 푸른빛을 띠어요. 구리 이온은 순수 비타민C(아스코빅애씨드)와 동시에 쓰면 서로 산화·환원 반응을 일으켜 두 성분 모두 불안정해질 수 있어 시간대를 나누는 것이 권장돼요. 낮은 pH의 산 제품과도 같은 단계 사용은 피하는 편이 흔하고, 아침·저녁 모두 사용돼요.',array['hyaluronic-acid','niacinamide','panthenol','peptides']::text[],array['ascorbic-acid','glycolic-acid','salicylic-acid']::text[],array['firming','texture']::text[],'Pickart L & Margolina A, Int J Mol Sci 2018; Gorouhi F & Maibach HI, Int J Cosmet Sci 2009','moderate','2026-07-02','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('argireline','아세틸헥사펩타이드-8','Acetyl Hexapeptide-8',array['firming']::text[],'plum','표정 주름 신호를 완화하는 개념으로 설계된 펩타이드로, 아이크림·세럼에 자주 쓰여요.','신경전달물질 방출에 관여하는 SNAP-25 단백질의 일부를 모방한 여섯 개 아미노산 펩타이드로, 근육 수축 신호를 부분적으로 줄여 표정 주름의 깊이를 완화하는 개념으로 설계됐어요. 이 때문에 흔히 "바르는 보톡스"로 소개되지만, 피부 침투와 실제 작용 크기에 대해서는 소규모 연구만 있어 근거가 제한적이에요. 자극이 매우 낮고 물에 잘 녹아 다른 활성 성분과 겹쳐 쓰기 무난하며, 5~10% 원료 용액 기준으로 배합되는 경우가 많아요. 아침·저녁 모두 사용되고 눈가·이마 부위 제품에 자주 들어가요.',array['peptides','hyaluronic-acid','adenosine','niacinamide']::text[],'{}'::text[],array['firming']::text[],'Blanes-Mira C et al., Int J Cosmet Sci 2002; Wang Y et al., Am J Clin Dermatol 2013','limited','2026-07-04','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('pdrn','PDRN','Sodium DNA',array['firming','renewal']::text[],'plum','연어 DNA 조각에서 얻은 성분으로, 재생 케어 컨셉의 앰플·크림에 자주 쓰여요.','연어 정소 등에서 추출한 DNA 조각(폴리데옥시리보뉴클레오타이드, PDRN)의 나트륨염으로, 의료 영역에서는 주사·창상 제제로 아데노신 A2A 수용체를 자극해 조직 회복을 돕는 기전이 연구되었어요. 화장품에서는 분자가 커서 각질층 침투가 제한적이라 표면에서 수분막을 형성하는 보습·컨디셔닝 역할이 주로 기대되며, 사람 피부에 바른 임상 자료는 아직 소규모예요. 자극이 낮은 편이라 아침·저녁 모두 사용되고 시술 후 케어 컨셉 제품에 자주 들어가요. 반응은 개인차가 있을 수 있어요.',array['hyaluronic-acid','panthenol','centella','ceramide']::text[],'{}'::text[],array['firming','texture','barrier']::text[],'Squadrito F et al., Front Pharmacol 2017; CIR Expert Panel','limited','2026-07-06','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('egf','EGF','sh-Oligopeptide-1',array['firming','renewal']::text[],'plum','피부 세포 성장 인자를 모방한 펩타이드로, 재생·탄력 컨셉 앰플에 쓰이는 성분이에요.','표피성장인자(EGF)와 같은 아미노산 서열을 재조합 기술로 만든 펩타이드로, 세포막의 EGF 수용체에 결합해 각질형성세포와 섬유아세포의 증식 신호를 보내는 것으로 알려져 있어요. 다만 분자량이 6kDa 정도로 커서 손상되지 않은 각질층을 통과하기 어렵고, 열·pH에 민감해 제형 안정성이 중요하다는 점이 자주 지적돼요. 국내에서는 화장품 원료로 배합 한도(0.001%)가 정해져 있고, 아침·저녁 모두 사용돼요. 시술 후 케어 제품에 자주 들어가지만 독립적인 장기 임상 자료는 제한적이에요.',array['hyaluronic-acid','peptides','panthenol','pdrn']::text[],array['glycolic-acid','salicylic-acid']::text[],array['firming']::text[],'식약처 화장품 안전기준 사용제한 원료; Schouest JM et al., J Drugs Dermatol 2012','limited','2026-07-08','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('caffeine','카페인','Caffeine',array['firming','antioxidant']::text[],'plum','커피의 그 카페인으로, 눈가 부기와 칙칙함을 다루는 아이크림에 자주 쓰이는 성분이에요.','혈관을 일시적으로 수축시키고 조직의 수분 배출을 돕는 작용이 알려져 있어, 눈가 부기와 다크서클 관련 아이크림·롤온 제품에 1~3% 수준으로 자주 배합돼요. 항산화 작용과 자외선으로 손상된 세포의 제거를 돕는 결과도 실험실 연구에서 보고되었어요. 물에 잘 녹고 피부 침투가 비교적 좋은 편으로 알려져 있으며, 아침에 발라 부기를 다루는 용도로 소개되는 경우가 많아요. 국소 사용에서 자극 보고는 드문 편이지만 반응은 개인차가 있을 수 있어요.',array['hyaluronic-acid','niacinamide','peptides','green-tea']::text[],'{}'::text[],array['firming','dullness']::text[],'Herman A & Herman AP, Skin Pharmacol Physiol 2013; CIR Expert Panel','moderate','2026-07-10','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('titanium-dioxide','티타늄디옥사이드','Titanium Dioxide',array['sunscreen']::text[],'butter','빛을 반사·산란시키는 무기 자외선 차단제로, 백탁이 있지만 자극이 적은 편으로 알려져 있어요.','징크옥사이드와 함께 대표적인 무기(물리적) 자외선 차단 필터로, UVB와 UVA2(짧은 UVA) 영역을 주로 차단하고 UVA1(장파장) 커버는 상대적으로 약한 편이에요. 그래서 UVA1을 보완하는 징크옥사이드나 유기 필터와 함께 배합되는 경우가 많아요. 피부에 거의 흡수되지 않고 표면에서 작용해 예민한 피부·어린이용 제품에 자주 쓰이지만, 입자가 빛을 반사해 백탁이 생길 수 있고 나노 입자는 이를 줄인 형태예요. 국내 배합 한도는 25%이며, 충분한 양(얼굴 기준 약 0.8~1g)을 바르고 2~3시간마다 덧바르는 것이 권장돼요.',array['zinc-oxide','tinosorb-s','niacinamide','tocopherol']::text[],'{}'::text[],array['pigmentation']::text[],'FDA Sunscreen Monograph; EU SCCS Opinion (Titanium Dioxide nano, SCCS/1516/13)','high','2026-07-12',array['filter']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('zinc-oxide','징크옥사이드','Zinc Oxide',array['sunscreen','soothing']::text[],'butter','UVA·UVB를 폭넓게 커버하는 무기 자외선 차단제로, 진정 목적으로도 오래 쓰여 온 성분이에요.','무기(물리적) 필터 중 UVB부터 UVA1(장파장)까지 가장 넓은 범위를 단독으로 커버하는 성분으로, 티타늄디옥사이드보다 UVA 보호가 넓지만 단위 농도당 UVB 차단력은 조금 낮은 편이에요. 피부에 거의 흡수되지 않고 표면에 머무르며, 기저귀 발진 연고에 쓰일 만큼 진정·수렴 작용이 오래 알려져 있어 트러블 경향 피부의 선크림에도 자주 쓰여요. 백탁과 건조한 사용감이 단점이라 나노화하거나 오일과 조합해 개선한 제품이 많고, 국내 배합 한도는 25%예요. 충분한 양을 바르고 땀·마찰 후 덧바르는 것이 권장돼요.',array['titanium-dioxide','niacinamide','squalane','tinosorb-s']::text[],'{}'::text[],array['pigmentation','breakout']::text[],'FDA Sunscreen Monograph; EU SCCS Opinion (Zinc Oxide nano, SCCS/1489/12)','high','2026-07-13',array['filter']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('uvinul-a-plus','디에칠아미노하이드록시벤조일헥실벤조에이트','Diethylamino Hydroxybenzoyl Hexyl Benzoate',array['sunscreen']::text[],'butter','UVA 영역을 전담하는 유기 자외선 차단제로, 광안정성이 높아 유럽·아시아 선크림에 자주 쓰여요.','"유비뉼 A 플러스"라는 원료명으로 알려진 유기(화학적) UVA 필터로, 흡수 최대 파장이 354nm 부근이라 UVA1(장파장) 영역을 주로 담당해요. 아보벤존과 달리 빛에 안정적이어서 별도의 안정화제가 필요 없고, 다른 필터의 광안정성을 해치지 않는 것으로 알려져 있어요. UVB 커버는 없어 에칠헥실트리아존·티노소브 계열 같은 UVB 필터와 조합해 넓은 범위를 만들어요. 유럽과 한국에서 최대 10%까지 허용되며(미국 미승인), 피부 흡수가 낮은 편으로 보고돼요. 반응은 개인차가 있을 수 있어요.',array['uvinul-t150','tinosorb-s','titanium-dioxide','tocopherol']::text[],'{}'::text[],array['pigmentation']::text[],'EU SCCS Opinion; 식약처 화장품 안전기준(자외선 차단 성분 배합한도)','high','2026-07-15',array['filter']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('uvinul-t150','에칠헥실트리아존','Ethylhexyl Triazone',array['sunscreen']::text[],'butter','UVB 흡수력이 가장 강한 편에 속하는 유기 자외선 차단제로, 적은 양으로도 SPF를 높이는 데 쓰여요.','"유비뉼 T150"으로 알려진 유기(화학적) UVB 필터로, 흡수 최대 파장 314nm 부근에서 단위 농도당 UVB 흡수력이 승인된 필터 중 가장 높은 편이에요. 광안정성이 좋고 분자가 커서(약 823Da) 피부 흡수가 매우 낮은 것으로 보고되며, 유분에 녹는 성질이라 산뜻한 제형을 만들기 위한 배합 기술이 필요해요. UVA 커버는 거의 없어 UVA 필터(유비뉼A플러스·티노소브S·아보벤존 등)와 함께 배합돼요. 유럽·한국 최대 5%까지 허용되고 미국에서는 미승인이에요. 반응은 개인차가 있을 수 있어요.',array['uvinul-a-plus','tinosorb-s','avobenzone','zinc-oxide']::text[],'{}'::text[],array['pigmentation']::text[],'EU SCCS Opinion; 식약처 화장품 안전기준(자외선 차단 성분 배합한도)','high','2026-07-17',array['filter']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('tinosorb-s','비스에칠헥실옥시페놀메톡시페닐트리아진','Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine',array['sunscreen']::text[],'butter','UVA와 UVB를 모두 흡수하는 광대역 유기 차단제로, 광안정성이 높아 유럽·아시아에서 널리 쓰여요.','"티노소브 S" 또는 베모트리지놀로 알려진 유기(화학적) 필터로, 310nm와 345nm 부근 두 개의 흡수 봉우리를 가져 UVB와 UVA1을 한 성분으로 넓게 커버해요. 빛에 매우 안정적이고 아보벤존 같은 불안정한 필터를 함께 안정화하는 것으로 알려져 있으며, 분자가 커서(약 627Da) 피부 흡수가 낮고 호르몬 관련 활성이 관찰되지 않았다는 평가가 있어요. 유럽·한국 최대 10%까지 허용되고 미국에서는 아직 승인 절차가 진행 중이에요. 유용성이라 산뜻하게 만들려면 배합 기술이 필요하고, 반응은 개인차가 있을 수 있어요.',array['avobenzone','uvinul-a-plus','uvinul-t150','zinc-oxide']::text[],'{}'::text[],array['pigmentation']::text[],'EU SCCS Opinion; Chatelain E & Gabard B, Photochem Photobiol 2001','high','2026-07-19',array['filter']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('avobenzone','부틸메톡시디벤조일메탄','Butyl Methoxydibenzoylmethane',array['sunscreen']::text[],'butter','전 세계에서 가장 널리 쓰이는 유기 UVA 차단제로, 빛에 약해 안정화 성분과 함께 배합돼요.','흡수 최대 파장 357nm 부근의 유기(화학적) UVA1 필터로, 미국 FDA와 EU·한국 모두 승인된 몇 안 되는 장파장 UVA 필터라 전 세계 선크림에 가장 널리 쓰여요. 다만 자외선을 받으면 스스로 분해되는 광불안정성이 있어, 옥토크릴렌·티노소브S·유비뉼A플러스 같은 안정화 필터나 항산화제와 함께 배합하는 것이 일반적이에요. 무기 필터(징크옥사이드·티타늄디옥사이드)와 같은 제형에 넣으면 분해가 빨라질 수 있어 조합을 피하는 처방이 많아요. 미국·한국 최대 3~5%로 허용되며, 드물게 접촉 알레르기와 광알레르기가 보고돼 반응은 개인차가 있을 수 있어요.',array['tinosorb-s','uvinul-t150','tocopherol']::text[],array['zinc-oxide','titanium-dioxide']::text[],array['pigmentation']::text[],'FDA Sunscreen Monograph (21 CFR 352); Chatelain E & Gabard B, Photochem Photobiol 2001','high','2026-07-21',array['filter']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('lavender-oil','라벤더오일','Lavandula Angustifolia (Lavender) Oil',array['soothing']::text[],'mint','라벤더 꽃에서 증류한 에센셜오일로, 향과 진정 목적으로 쓰이지만 향료 알레르기 유발 성분을 포함해요.','리날룰과 리날릴아세테이트가 주요 성분인 에센셜오일로, 아로마 효과와 가벼운 항균 작용을 이유로 진정·트러블 컨셉 제품에 배합돼요. 다만 리날룰은 공기 중에서 산화되면 접촉 감작(알레르기 반응)을 일으키는 물질로 바뀌며, EU에서 표시 의무가 있는 향료 알레르겐 목록에 포함돼 있어요. 오일 자체가 각질세포에 손상을 줄 수 있다는 실험실 연구도 있어, 화장품에서는 대개 1% 미만으로 희석해 쓰여요. 여러 향 제품과 겹치면 누적 노출이 늘어나므로 예민한 피부는 향료 무첨가 제품을 우선 고려하는 것이 권장되고, 오래된 제품은 산화되었을 수 있어요.',array['jojoba-oil','sunflower-oil']::text[],array['tea-tree','citrus-oil','retinol']::text[],array['breakout']::text[],'EU SCCS Opinion on Fragrance Allergens (SCCS/1459/11); Prashar A et al., Cell Prolif 2004','limited','2026-07-23',array['essential-oil','fragrance']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('rose','로즈(다마스크장미)','Rosa Damascena Flower Water',array['soothing','hydration']::text[],'mint','다마스크 장미를 증류해 얻은 꽃수로, 부드러운 향과 가벼운 보습감 때문에 토너에 자주 쓰여요.','장미 오일을 수증기 증류할 때 함께 얻어지는 수용성 부분(하이드로졸)으로, 미량의 향 성분과 페놀류가 물에 녹아 있어요. 오일보다 향 성분 농도가 훨씬 낮아 순한 편으로 알려져 있지만, 시트로넬롤·제라니올 같은 표시 의무 향료 알레르겐이 소량 들어 있어 향에 민감한 피부는 반응을 살펴보는 것이 권장돼요. 토너·미스트의 물 베이스 대신 쓰여 보습감과 향을 더하는 역할이 주된 목적이고, 그 자체의 톤·진정 작용에 대한 임상 자료는 제한적이에요. 아침·저녁 모두 사용되며 반응은 개인차가 있을 수 있어요.',array['hyaluronic-acid','glycerin','aloe','niacinamide']::text[],'{}'::text[],array['dullness','dryness']::text[],'CIR Expert Panel (Rosa Damascena); EU SCCS Opinion on Fragrance Allergens','limited','2026-07-25',array['fragrance']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('citrus-oil','시트러스오일','Citrus Aurantium Dulcis (Orange) Peel Oil',array['antioxidant']::text[],'gold','오렌지 껍질에서 짜낸 에센셜오일로, 상큼한 향을 위해 쓰이지만 피부 자극과 광반응 주의가 필요해요.','리모넨이 90% 이상을 차지하는 에센셜오일로, 향과 항산화 컨셉으로 세안제·바디 제품에 배합돼요. 리모넨은 공기 중에서 산화되면 접촉 감작(알레르기 반응)을 일으키는 물질로 바뀌어 EU 표시 의무 알레르겐에 포함되고, 개봉 후 오래된 제품일수록 반응 가능성이 커질 수 있어요. 냉압착 방식의 시트러스 오일은 푸로쿠마린(베르갑텐 등)이 남아 햇빛과 만나면 광독성 반응을 일으킬 수 있어, 스위트오렌지는 비교적 낮은 편이지만 낮 사용 시 자외선 차단이 권장돼요. 다른 향 제품과 겹치면 누적 노출이 늘어나요.',array['jojoba-oil','sunflower-oil']::text[],array['lavender-oil','tea-tree','retinol','glycolic-acid']::text[],array['dullness']::text[],'EU SCCS Opinion on Fragrance Allergens (SCCS/1459/11); IFRA Standards (Citrus oils)','limited','2026-07-27',array['essential-oil','fragrance']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('fragrance','향료','Parfum',array['soothing']::text[],'mint','제품에 향을 더하는 성분들의 통칭으로, 성분표에 "향료" 한 단어로 표기되는 혼합물이에요.','"향료(Parfum/Fragrance)"는 수십~수백 가지 천연·합성 향 물질을 섞은 혼합물을 하나의 이름으로 표기한 것으로, 각 성분은 대개 공개되지 않아요. 향 자체가 피부에 주는 유익한 작용은 알려진 바가 없고, 사용감과 원료 냄새를 가리는 목적으로 배합돼요. 접촉 알레르기의 가장 흔한 원인 중 하나로 알려져 있어 EU와 한국은 리날룰·리모넨·제라니올 등 표시 의무 알레르겐을 별도로 적도록 정해 두었어요. 자극이 잦은 피부라면 향료 무첨가 제품을 우선 시도하고, 여러 제품의 향료가 겹치면 누적 노출이 늘어난다는 점을 참고하는 것이 권장돼요.',array['panthenol','allantoin']::text[],array['lavender-oil','citrus-oil','rosemary','tea-tree']::text[],'{}'::text[],'EU SCCS Opinion on Fragrance Allergens (SCCS/1459/11); 식약처 화장품 알레르기 유발성분 표시 고시','high','2026-07-29',array['fragrance']::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
insert into public.ingredients (id,name_ko,name_inci,categories,color_tag,short_desc,long_desc,pairs_well,pair_caution,related_concerns,source,evidence_level,last_reviewed,tags) values ('alcohol-denat','변성알코올','Alcohol Denat.',array['sebum']::text[],'butter','변성 처리한 에탄올로, 산뜻한 사용감과 빠른 건조를 위해 토너·선크림에 자주 쓰이는 성분이에요.','식용을 막기 위해 변성제를 넣은 에탄올로, 휘발하면서 산뜻하고 가벼운 마무리감을 주고 일부 성분의 용해·침투를 돕는 용매 역할을 해요. 성분표 앞쪽에 있을 만큼 고함량이면 피지와 함께 각질층 지질을 일부 녹여 일시적으로 보송해 보이지만, 반복 사용 시 건조·당김이 나타날 수 있다는 지적이 있어요. 반면 선크림이나 앰플에 소량 들어간 경우까지 문제 삼을 근거는 뚜렷하지 않아 성분표 위치와 본인 피부 상태를 함께 보는 것이 권장돼요. 지방알코올(세틸·스테아릴알코올)은 이름만 비슷할 뿐 보습·유화 성분으로 성질이 달라요.',array['glycerin','hyaluronic-acid','niacinamide','panthenol']::text[],array['retinol','glycolic-acid','salicylic-acid']::text[],array['sebum']::text[],'CIR Expert Panel Final Report (Alcohol Denat.); Lachenmeier DW, J Occup Med Toxicol 2008','moderate','2026-08-01','{}'::text[]) on conflict (id) do update set name_ko=excluded.name_ko,name_inci=excluded.name_inci,categories=excluded.categories,color_tag=excluded.color_tag,short_desc=excluded.short_desc,long_desc=excluded.long_desc,pairs_well=excluded.pairs_well,pair_caution=excluded.pair_caution,related_concerns=excluded.related_concerns,source=excluded.source,evidence_level=excluded.evidence_level,last_reviewed=excluded.last_reviewed,tags=excluded.tags;
